local config = {
  ui_story_2001_1_X1_dialog_content = "<color=#e8d9bb>Terra árida na zona rural de Lumópolis</color>",
  ui_story_2001_1_X2_dialog_content = "<color=#e8d9bb>Uma enxurrada de veículos passou correndo desenfreada em nuvens de poeira, com barulhos de rádio e motores que aumentavam ao se aproximarem, até balançarem as bandeiras de Rediesels no horizonte.</color>",
  ui_story_2001_1_1_dialog_content = "Haha, faturamos alto hoje! Já tava na hora de ganharmos algo bom como a Caravana de Lumópolis!",
  ui_story_2001_1_2_dialog_content = "Agora só nos resta comemorar... Uhul!",
  ui_story_2001_1_3_dialog_content = "Sou só eu ou a cidade acima da gente tá ficando maior?",
  ui_story_2001_1_4_dialog_content = "Tem certeza que não estamos indo na direção errada, Brock?",
  ui_story_2001_1_5_dialog_content = "Hã? O que você tá dizendo? Tô com os olhos colados no mapa!",
  ui_story_2001_1_6_dialog_content = "Ele não diz aqui \"4,8 quilômetros ao norte das ruínas\"? Humm... Qual é o nome das ruínas...",
  ui_story_2001_1_7_dialog_content = "Hum, Brock... Existe a possibilidade de você... Cof... Tipo...",
  ui_story_2001_1_8_dialog_content = "<size=45>ter lido o mapa de cabeça pra baixo?</size>",
  ui_story_2001_1_9_dialog_content = "<size=45>O quê??? Droga, de quem foi a ideia de fazer um mapa que ninguém consegue ler?!</size>",
  ui_story_2001_1_10_dialog_content = "Por que estou andando pra cima e pra baixo no meio do nada com um pedaço de papel inútil?!",
  ui_story_2001_1_11_dialog_content = "Hum, talvez por ter pisado e quebrado o sinal dos Parafusos Soltos enquanto lutava anteriormente?",
  ui_story_2001_1_12_dialog_content = "Cala a boca, quem te perguntou? Enfim, eles deveriam ter feito esse mapa pra durar mais!",
  ui_story_2001_1_13_dialog_content = "Nossa! Ali! Alguém está vindo em nossa direção!",
  ui_story_2001_1_14_dialog_content = "Favor cooperar e parar seus veículos para a inspeção de Lumópolis! Repito, parem seus veículos!",
  ui_story_2001_1_15_dialog_content = "É a <color=#FFB400>Patrulha</color> de Lumópolis! Eles são rápidos, e pro nosso azar, há um monte deles...",
  ui_story_2001_1_16_dialog_content = "Hunf! Bem a tempo pra eu descontar nesses otários!",
  ui_story_2001_1_17_dialog_content = "Espere, são...! Criminosos procurados avistados entre os suspeitos, solicitando reforços...",
  ui_story_2001_1_18_dialog_content = "Nossa, caiu com apenas um acerto... Pessoal, fiquem atentos, cerquem o alvo!",
  ui_story_2001_2_1_dialog_content = "O quê? É só isso? Posso capturar todos vocês sozinho!",
  ui_story_2001_2_2_dialog_content = "Que decepção. Vocês não têm caras mais fortes?",
  ui_story_2001_2_3_dialog_content = "B-Brock!",
  ui_story_2001_2_4_dialog_content = "O quê! Ei, que feridas são essas?",
  ui_story_2001_2_5_dialog_content = "Foram os caras de Lumópolis... Eles nos atacaram por outro lado e apreenderam nossas coisas. O líder deles...*tosse*... É melhor tomar cuidado...",
  ui_story_2001_2_6_dialog_content = "Entendi. Shh, pare de falar, você tá ferido!",
  ui_story_2001_2_7_dialog_content = "Quem ousou saquear a Rediesel Wrench? Vou virar motivo de chacota! Não, tenho que pegar nossas coisas de volta!",
  ui_story_2001_2_8_dialog_content = "Todos que ainda puderem se mover, me deem cobertura. Vou usar o treco novo que fizeram pra gente!",
  ui_story_2001_2_9_dialog_content = "<color=#e8d9bb>Vários raios atingiram a área à frente de Brock, criando explosões ensurdecedoras antes que ele pudesse reagir, e qualquer uma delas poderia tê-lo torrado.</color>",
  ui_story_2001_2_10_dialog_content = "Você parece saber de algumas coisas... Você deve ser a líder do esquadrão de Lumópolis.",
  ui_story_2001_2_11_dialog_content = "Seu Senhor não a ensinou a não mexer com as coisas dos outros?",
  ui_story_2001_2_12_dialog_content = "...",
  ui_story_2001_2_13_dialog_content = "<color=#e8d9bb>Brock não obteve resposta, a não ser a respiração pesada sob a máscara do seu oponente e a chiadeira do campo elétrico.</color>",
  ui_story_2001_2_14_dialog_content = "Ei! Não me menospreze!",
  ui_story_2001_2_15_dialog_content = "Muito bem! Mostre do que é capaz!",
  ui_story_2001_2_16_dialog_content = "...",
  ui_story_2001_2_17_dialog_content = "Hum, nada mal, acho que nem todo mundo em Lumópolis é péssimo.",
  ui_story_2001_2_18_dialog_content = "Já que você bateu nos meus caras, tenho que te dar uma surra pra ficarmos quites!",
  ui_story_2001_2_19_dialog_content = "...",
  ui_story_2001_2_20_dialog_content = "Já carregamos as coisas e os feridos, Brock. Temos que sair daqui!",
  ui_story_2001_2_21_dialog_content = "Tá bem! Você devia agradecer por eu não...",
  ui_story_2001_2_22_dialog_content = "<color=#e8d9bb>Outro raio passou por Brock, raspando a ponta de seu nariz, deixando uma marca no chão, alguns centímetros atrás dele.</color>",
  ui_story_2001_2_23_dialog_content = "<color=#e8d9bb>Brock notou várias pessoas, vestidas de forma idêntica, aparecendo ao lado da figura mascarada</color>",
  ui_story_2001_2_24_dialog_content = "Ihh! Foi mal, foi mal! É minha culpa estarmos todos perdidos!",
  ui_story_2001_2_25_dialog_content = "Você está bem, pequena <color=#FFB400>Michele</color>? Deixe-me fazer um curativo em você!",
  ui_story_2001_2_26_dialog_content = "Qual o problema desses velhos nobres malucos de Lumópolis, mandando garotinhas magrelas pra lutar?",
  ui_story_2001_2_27_dialog_content = "Não quero bater em crianças, mas já que começaram, vou acabar com isso!",
  ui_story_2001_2_28_dialog_content = "O resto de vocês pode meter o pé pra não atrapalhar o meu show! E não bebam tudo antes de eu voltar!",
  ui_story_2001_2_29_dialog_content = "Vamos atrás dos bandidos, <color=#FFB400>Madame Carleen</color>...",
  ui_story_2001_2_30_dialog_content = "Não se preocupe.",
  ui_story_2001_2_31_dialog_content = "Michele, Raphaela e o resto da patrulha, aguardem.",
  ui_story_2001_2_32_dialog_content = "Ignorem os ratos e foquem na ameaça maior.",
  ui_story_2001_2_33_dialog_content = "Ah, você é perspicaz. Afinal, eu SOU o segundo no comando da Rediesel Wrench! Venha aqui provar um pouco disso... Arrrgh!",
  ui_story_2001_2_34_dialog_content = "(O que diabos aconteceu? Por que o chão... Eu caí?)",
  ui_story_2001_2_35_dialog_content = "...",
  ui_story_2001_2_36_dialog_content = "(O que a mulher mascarada fez comigo? Não consigo me mover...!)",
  ui_story_2001_2_37_dialog_content = "Bom trabalho, Michele.",
  ui_story_2001_2_38_dialog_content = "Sou a Capitã Carleen dos Guardiões. Brock da Rediesel Wrench, você está preso!",
  ui_story_2001_3_1_dialog_content = "Ficou sabendo? Os Guardiões prenderam outro chefe da Rediesel Wrench, talvez seja até o segundo no comando dessa vez.",
  ui_story_2001_3_2_dialog_content = "Sim, é bem melhor do que capturar um bando de peões inúteis.",
  ui_story_2001_3_3_dialog_content = "Espere até a comemoração acabar. Será o fim pra esses otários...",
  ui_story_2001_3_4_dialog_content = "(Onde estou?)",
  ui_story_2001_3_5_dialog_content = "Ai, ai, ai! Ei, parece que ainda estou vivo!",
  ui_story_2001_3_6_dialog_content = "Tsc, onde eles arrumavam aqueles esquisitos que resolviam os problemas deles...? E será que aqueles idiotas barulhentos escaparam...?",
  ui_story_2001_3_7_dialog_content = "Hah! E eu tava me perguntando quem poderia ser o otário fanfarrão!",
  ui_story_2001_3_8_dialog_content = "Quem você tá chamando de otário fanfarrão? Posso estar meio distraído hoje, mas se aquele cara não tivesse me atacado por trás... Espere aí, quem está falando?!",
  ui_story_2001_3_9_dialog_content = "<size=40>Já faz um tempo, Brock.</size>",
  ui_story_2001_3_10_dialog_content = "<color=#e8d9bb>Uma mulher saiu da sombra, com um olhar traiçoeiro para Brock.</color>",
  ui_story_2001_3_11_dialog_content = "<color=#e8d9bb>Brock sentiu um cheiro de pólvora intenso, porém familiar, e olhou para ela na penumbra.</color>",
  ui_story_2001_3_12_dialog_content = "<color=#FFB400>Jona</color>? O que está fazendo aqui?",
  ui_story_2001_3_13_dialog_content = "E, hum, onde estamos?",
  ui_story_2001_3_14_dialog_content = "No corredor da morte de Lumópolis. Mas pra dizer a verdade, esqueci como cheguei aqui...",
  ui_story_2001_3_15_dialog_content = "Devia estar hospedada em alguma espelunca, participando de um desafio de bebida com alguém sem a menor noção e acabei acordando aqui.",
  ui_story_2001_3_16_dialog_content = "Ai, ai, algum caçador ou espião Lumo deve ter ganhado um bom dinheiro às minhas custas.",
  ui_story_2001_3_17_dialog_content = "Mas, sinceramente, pelo prêmio que eles ofereceram pela minha cabeça, eu mesma tentaria coletá-lo se pudesse!",
  ui_story_2001_3_18_dialog_content = "<color=#e8d9bb>Jona contou sua situação como se zombasse de outra pessoa, sua risada reverberava pelas paredes da cela.</color>",
  ui_story_2001_3_19_dialog_content = "Não admira que tenha sumido após a última missão. Droga, Lumópolis, se ao menos os caras tivessem obtido as informações antes! Ai!",
  ui_story_2001_3_20_dialog_content = "Cuidado. É uma ferida recente, não é? Vai abrir novamente se você não for cuidadoso.",
  ui_story_2001_3_21_dialog_content = "O que eles servem aqui é aceitável, e não tem o Sinsa reclamando de tudo, então na verdade não é tão ruim.",
  ui_story_2001_3_22_dialog_content = "Mas ficar relaxando... não, quero dizer, ficar trancada sem nada pra fazer tá ficando chato.",
  ui_story_2001_3_23_dialog_content = "Além disso, colocar dois instrutores da Rediesel Wrench no corredor da morte na mesma cela é sufocante. Não quero um troglodita como companheiro de cela.",
  ui_story_2001_3_24_dialog_content = "Tá resmungando o que aí? E você me insultou assim, sem mais nem menos?",
  ui_story_2001_3_25_dialog_content = "Enfim...",
  ui_story_2001_3_26_dialog_content = "<color=#e8d9bb>Jona estalou o pescoço e os dedos e, antes que Brock pudesse reagir,</color>",
  ui_story_2001_3_27_dialog_content = "<size=45><color=#e8d9bb>um grande buraco tinha sido explodido na parede.</color></size>",
  ui_story_2001_3_28_dialog_content = "Vou tirar você daqui, então é melhor conseguir acompanhar!",
  ui_story_2001_4_1_dialog_content = "Explosão no Complexo de Segurança Máxima, possível violação! Equipe de Segurança, vá ao local imediatamente...",
  ui_story_2001_4_2_dialog_content = "Ugh!",
  ui_story_2001_4_3_dialog_content = "Cinquenta e um policiais Lumo derrotados. São fáceis de lidar, comparado com os irritantes mecanismos de segurança.",
  ui_story_2001_4_4_dialog_content = "<color=#e8d9bb>Brock disse isso em voz alta de propósito enquanto olhava para Jona, que não parecia estar prestando atenção.</color>",
  ui_story_2001_4_5_dialog_content = "Ei, e você?",
  ui_story_2001_4_6_dialog_content = "Hã? É uma competição? Eu não estava contando... Bota cinquenta então.",
  ui_story_2001_4_7_dialog_content = "Jona, você tá me subestimando, não é?",
  ui_story_2001_4_8_dialog_content = "Nunca, ainda mais o \"segundo no comando da Rediesel\"! Você deve estar a apenas um passo de derrubar o Sinsa e ocupar o primeiro lugar, não é?",
  ui_story_2001_4_9_dialog_content = "De onde você tirou isso? Isso foi apenas uma mentira pra ganhar tempo pro nosso pessoal fugir!",
  ui_story_2001_4_10_dialog_content = "Tá, tanto faz. Ninguém tá rindo das suas aspirações, mesmo que esteja perdendo pra ele por 728 a 0, com 3 empates...",
  ui_story_2001_4_11_dialog_content = "Humm, acho que estamos no perímetro externo de Lumópolis agora.",
  ui_story_2001_4_12_dialog_content = "Ah. O que isso significa?",
  ui_story_2001_4_13_dialog_content = "Aquela é uma aeronave da Patrulha Lumo. Parece que estamos em um pequeno <color=#FFB400>centro de transporte</color>.",
  ui_story_2001_4_14_dialog_content = "Boa. Eles já me perseguiram o bastante, já era hora de eu dar uma voltinha em um!",
  ui_story_2001_4_15_dialog_content = "Ei, espere...",
  ui_story_2001_4_16_dialog_content = "Ai, ai... Por que nós temos que ser as responsáveis por encontrá-los?",
  ui_story_2001_4_17_dialog_content = "Era pra ser a hora do meu cochilo. Um cronograma de descanso bagunçado certamente não leva a nada de bom.",
  ui_story_2001_4_18_dialog_content = "Em breve estaria tudo acabado pra vocês, dando um fim à sua dor. Por que escapar?",
  ui_story_2001_4_19_dialog_content = "Poderiam ter dado adeus a tudo isso, e eu ficaria até com inveja.",
  ui_story_2001_4_20_dialog_content = "Droga. Temos companhia, Jona! Essas duas são...?",
  ui_story_2001_4_21_dialog_content = "Os Anjos da Guarda dos Cavaleiros! Vejo que as histórias são verdadeiras...",
  ui_story_2001_4_22_dialog_content = "Não se engane por sua aparência, elas são até...",
  ui_story_2001_4_23_dialog_content = "...mais bonitas do que nas histórias!",
  ui_story_2001_4_24_dialog_content = "Hã?",
  ui_story_2001_4_25_dialog_content = "Considerando o que desperdiça de recursos abundantes da civilização antiga e sua preferência pelas elites nas nuvens, pensei que Lumópolis fosse o poço da devassidão.",
  ui_story_2001_4_26_dialog_content = "Com certeza eu não esperava ver um monte de guerreiras tão bonitas entre seus Cavaleiros! Que desperdício.",
  ui_story_2001_4_27_dialog_content = "Alou, elas são inimigas! Eu não me importo se elas são mulheres gatas ou demônios do inferno.",
  ui_story_2001_4_28_dialog_content = "Você não terá muitas chances de falar com garotas bonitas, Brock. Deveria valorizar esse momento.",
  ui_story_2001_4_29_dialog_content = "Não é da sua conta! Jona! Acho que elas vão atacar!",
  ui_story_2001_4_30_dialog_content = "<color=#e8d9bb>O ataque delas passou por Brock, destruindo a aeronave e qualquer esperança de escapar nela.</color>",
  ui_story_2001_4_31_dialog_content = "Droga, a aeronave...!",
  ui_story_2001_4_32_dialog_content = "Hihi! Que convidados cheios de energia! Não acha, Uriel querida? Posso... aproveitar um pouco mais...?",
  ui_story_2001_4_33_dialog_content = "Chega, Gabriela. Antes que mais guardas apareçam...",
  ui_story_2001_4_34_dialog_content = "...vamos mandá-los para... o descanso eterno.",
  ui_story_2001_4_35_dialog_content = "Hahahahahaha!",
  ui_story_2001_4_36_dialog_content = "Muito bem, faz tempo que não vejo tanta ação! Não fiquem aí paradas, vocês duas precisam acompanhar o ritmo também!",
  ui_story_2001_4_37_dialog_content = "Arf, arf...",
  ui_story_2001_4_38_dialog_content = "É, pra você é fácil falar... O quê? Vocês são...!",
  ui_story_2001_4_39_dialog_content = "<color=#e8d9bb>Duas figuras familiares desceram novamente diante de um Brock enfraquecido.</color>",
  ui_story_2001_4_40_dialog_content = "...",
  ui_story_2001_4_41_dialog_content = "Espere por mim, Michele! Suas feridas acabaram de curar, correr tão rápido assim vai...",
  ui_story_2001_4_42_dialog_content = "Talvez você precise checar os seus olhos... Obviamente é uma garota.",
  ui_story_2001_4_43_dialog_content = "Uhuuull! Hoje deve ser o meu dia de sorte! Todos os quatro anjos em um só lugar!",
  ui_story_2001_4_44_dialog_content = "Você quer dizer dia do juízo final? Enfrentar todas as quatro de uma vez, mesmo sendo você e eu...",
  ui_story_2001_4_45_dialog_content = "Eu cuido disso, Jona! Veja se consegue achar outras pessoas por aí...",
  ui_story_2001_4_46_dialog_content = "Deixe o discurso deprê pra outra hora, sim? Eu disse que vou tirar você daqui, então vai ser constrangedor se eu não conseguir.",
  ui_story_2001_4_47_dialog_content = "Essa viagem vale a pena. Não esperava menos de Lumópolis!",
  ui_story_2001_4_48_dialog_content = "Agora entendo por que tantos desesperados se reúnem aqui na esperança de serem escolhidos um dia.",
  ui_story_2001_4_49_dialog_content = "Felizmente, é muito mais fácil ir embora.",
  ui_story_2001_4_50_dialog_content = "<size=45>Adeus, anjinhos!</size>",
  ui_story_2001_4_51_dialog_content = "<color=#e8d9bb>Jona agarrou Brock e <color=#FFB400>saltou</color></color> da borda do centro de transporte.",
  ui_story_2001_4_52_dialog_content = "<color=#e8d9bb>A abrupta ausência de peso causou calafrios por todas as suas células.</color>",
  ui_story_2001_4_53_dialog_content = "Comida e hospedagem podem melhorar bastante, porém, o serviço foi ótimo! Vejo vocês na próxima!",
  ui_story_2001_4_54_dialog_content = "Arghhhhh!",
  ui_story_2001_4_55_dialog_content = "<size=45>Nós vamos morrer!!</size>",
  ui_story_2001_4_56_dialog_content = "<color=#e8d9bb>Brock gritou e sufocou enquanto sua visão escurecia...</color>",
  ui_story_2001_5_1_dialog_content = "...",
  ui_story_2001_5_2_dialog_content = "Ei, vai ficar de grosseria por muito tempo ainda? Eu pedi desculpas, não pedi?",
  ui_story_2001_5_3_dialog_content = "Não estou...",
  ui_story_2001_5_4_dialog_content = "Que covarde. Nunca ouvi um grito tão deplorável assim antes.",
  ui_story_2001_5_5_dialog_content = "Eu tenho medo de altura! E afinal, quem seria louco o suficiente pra pular de Lumópolis?!",
  ui_story_2001_5_6_dialog_content = "Você tem que se surpreender antes de surpreender o inimigo.",
  ui_story_2001_5_7_dialog_content = "Elas certamente não esperavam por isso, não é? Pode chamar de improvisação de Rediesel Wrench! Hah!",
  ui_story_2001_5_8_dialog_content = "Improvisação? Então estava falando sério quando disse que aterrissamos em segurança graças à força do recuo da arma?",
  ui_story_2001_5_9_dialog_content = "O recuo deve ter algo a ver com isso, claro, mas principalmente...",
  ui_story_2001_5_10_dialog_content = "Sua poderosa Lúmina, apesar de enfraquecida pelas algemas?",
  ui_story_2001_5_11_dialog_content = "Foi principalmente SORTE! Huahahaha!",
  ui_story_2001_5_12_dialog_content = "Você vai ser a primeira que eu vou matar assim que assumir o lugar de Sinsa.",
  ui_story_2001_5_13_dialog_content = "Sério? Mal posso esperar, então. Claro, considerando que eu viva o suficiente pra que isso finalmente aconteça.",
  ui_story_2001_5_14_dialog_content = "Que tal irmos em direção à Umbraton pra tomar uma bebida? Talvez a gente consiga até pegar uma carona...",
  ui_story_2001_5_15_dialog_content = "Ei, ali, parece uma bandeira dos <color=#FFB400>Parafusos Soltos</color>!",
  ui_story_2001_5_16_dialog_content = "Vejo que vocês dois se divertiram e Jona parece até ter engordado.",
  ui_story_2001_5_17_dialog_content = "O que me irrita é o fato de vocês terem me deixado de fora dessa luta divertida em Lumópolis.",
  ui_story_2001_5_18_dialog_content = "Heh, nós até vimos os quatro anjos de uma só vez! Não é, Brock?",
  ui_story_2001_5_19_dialog_content = "Hum, é...",
  ui_story_2001_5_20_dialog_content = "O que há com ele, não tomou café da manhã?",
  ui_story_2001_5_21_dialog_content = "Deixe pra lá. O chefão me mandou te buscar, contanto que eu o leve inteiro de volta...",
  ui_story_2001_5_22_dialog_content = "Tô vendo que Sinsa de fato age como se fosse o mandachuva de vez em quando.",
  ui_story_2001_5_23_dialog_content = "Pra ser exata, estávamos todos com desejo do restaurante de lámen em Umbraton, então não custava ver se conseguíamos te pegar, já que é caminho.",
  ui_story_2001_5_24_dialog_content = "Enfim, de acordo com o pessoal de tecnologia, esse lugar deve ficar repleto de Eclipsitas em breve.",
  ui_story_2001_5_25_dialog_content = "Em breve?",
  ui_story_2001_5_26_dialog_content = "Foi o que Odi disse quando eu saí.",
  ui_story_2001_5_27_dialog_content = "Quer dizer que está quase na hora do show?",
  ui_story_2001_5_28_dialog_content = "Então temos que ir embora! Não temos condições de lidar com os Eclipsitas agora...",
  ui_story_2001_5_29_dialog_content = "Nós colocamos o rabo entre as pernas agora?",
  ui_story_2001_5_30_dialog_content = "Não, chama-se bom senso, bom senso! E também, Lumópolis não está atrás de nós?",
  ui_story_2001_5_31_dialog_content = "Ah, eles... Eles já estão aqui e esperando pra fazer uma emboscada.",
  ui_story_2001_5_32_dialog_content = "O quê?!",
  ui_story_2001_5_33_dialog_content = "Muito bem, vocês, Grisalhos, podem sair agora. Os Eclipsitas tão prontos pra atacar, então vamos acabar com isso rapidamente, beleza?",
  ui_story_2001_6_1_dialog_content = "Venham me pegar, todos vocês, vou mandar todo mundo pros ares!",
  ui_story_2001_6_2_dialog_content = "Até que Brock melhorou bem rápido... Ei, cuidado com a areia movediça!",
  ui_story_2001_6_3_dialog_content = "Ops. Tarde demais.",
  ui_story_2001_6_4_dialog_content = "Você acabou de tirar \"férias\" e vai ficar mais um período de folga agora, Jona?",
  ui_story_2001_6_5_dialog_content = "<color=#e8d9bb>A temperatura caiu drasticamente de repente, arrepiando todo mundo</color>",
  ui_story_2001_6_Q1_dialog_content = "Bem, parece que estamos presos com os Eclipsitas. Chega de brincadeiras.",
  ui_story_2001_6_Q2_dialog_content = "Eclipsitas? Grr... Que pragas! Se ao menos esses Grisalhos não tivessem nos atrasado...",
  ui_story_2001_6_Q3_dialog_content = "Espere, um confronto tão grande não destruiria a vizinhança... e nosso restaurante de lámen também?",
  ui_story_2001_6_Q4_dialog_content = "Você precisa escolher suas prioridades, Regina.",
  ui_story_2001_6_6_dialog_content = "Vejam aquilo ali. O que é aquilo se aproximando no meio dos Eclipsitas?",
  ui_story_2001_6_7_dialog_content = "Consigo ver daqui que não será um adversário fácil...",
  ui_story_2001_6_8_dialog_content = "Aahhhhhh!",
  ui_story_2001_6_9_dialog_content = "<color=#e8d9bb>Enquanto isso,</color>",
  ui_story_2001_6_10_dialog_content = "<color=#e8d9bb>os Guardiões de Lumópolis, que estavam perseguindo Brock, se envolveram em uma batalha com a horda de Eclipsitas.</color>",
  ui_story_2001_6_11_dialog_content = "Mantenham suas posições! Anjos primeiro, seguidos pelos esquadrões 3 e 7!",
  ui_story_2001_6_12_dialog_content = "O resto fica de prontidão aguardando meu comando!",
  ui_story_2001_6_13_dialog_content = "Capitã! O alvo rompeu a formação e está indo em direção ao assentamento!",
  ui_story_2001_6_14_dialog_content = "Os inimigos bloquearam nossas tropas! Também perdemos comunicação devido a interferências!",
  ui_story_2001_6_15_dialog_content = "Capitã Carleen, se as coisas continuarem assim...",
  ui_story_2001_6_16_dialog_content = "Ora, ora, que festinha animada temos aqui! Podemos nos juntar? Podemos, princesa dos Guardiões?",
  ui_story_2001_6_17_dialog_content = "Bem, já que perdi a diversão lá em cima, isso vai ter que servir!",
  ui_story_2001_6_18_dialog_content = "Vocês se atrevem a aparecer na minha frente?",
  ui_story_2001_6_19_dialog_content = "Pare de rosnar, querida. Não temos tempo pra flertar agora.",
  ui_story_2001_6_20_dialog_content = "Você...!",
  ui_story_2001_6_21_dialog_content = "Hah! O grandão é todo meu, se vocês forem ficar tagarelando!",
  ui_story_2001_6_22_dialog_content = "Vai sonhando, ele é o meu troféu!",
  ui_story_2001_6_23_dialog_content = "Ei, ei, vocês tão queimando a largada! Isso é trapaça! Voltem aqui!",
  ui_story_2001_6_24_dialog_content = "<color=#e8d9bb>A dupla brincou enquanto corria impulsivamente para o meio da batalha entre os Eclipsitas e os Guardiões...</color>",
  ui_story_2001_6_25_dialog_content = "Ca-capitã, parece que há uma abertura. Os Eclipsitas foram espalhados por aqueles dois...",
  ui_story_2001_6_26_dialog_content = "<color=#e8d9bb>Ao ver os desesperados rompendo a horda de Eclipsitas, Carleen virou-se e deu uma ordem aos Guardiões.</color>",
  ui_story_2001_6_27_dialog_content = "Todos ao ataque! Rompam a barreira deles!",
  ui_story_2001_6_28_dialog_content = "Não me faça errar, princesa.",
  ui_story_2001_6_29_dialog_content = "Essa fala é minha, sua terrorista! Lá vou eu!",
  ui_story_2001_6_30_dialog_content = "Ufa! Não há mais Eclipsitas. Acho que por hoje chega, e Lumópolis mal deu pro gasto.",
  ui_story_2001_6_31_dialog_content = "Todas as unidades registrem as vítimas imediatamente e iniciem o protocolo de primeiros socorros. Quero os relatórios até o final do dia. Desligo.",
  ui_story_2001_6_32_dialog_content = "Vejo que ser capitã também é um trabalho duro. Vou lhe deixar com seus afazeres. Até mais tarde!",
  ui_story_2001_6_33_dialog_content = "Pare.",
  ui_story_2001_6_34_dialog_content = "Jona, instrutora da Rediesel Wrench, devido às enormes perdas em Lumópolis e por fugir da prisão, eu declaro...",
  ui_story_2001_6_35_dialog_content = "Vai me prender? Você será sempre uma pessoa vazia se continuar arrogante desse jeito, princesa.",
  ui_story_2001_6_36_dialog_content = "Sua criminosa soberba, você vai pagar caro por sua insolência...",
  ui_story_2001_6_37_dialog_content = "<color=#e8d9bb>Antes que Carleen pudesse terminar, o chão começou a tremer de forma cadenciada, como se algo se aproximasse. Ela assumiu uma postura de batalha na hora, apenas para ver...</color>",
  ui_story_2001_6_38_dialog_content = "<size=45>Ei.</size>",
  ui_story_2001_6_39_dialog_content = "Por que demorou tanto, chefão?",
  ui_story_2001_6_40_dialog_content = "Haha, nada me acorda da minha soneca da tarde.",
  ui_story_2001_6_41_dialog_content = "Você é Sinsa? O líder de...",
  ui_story_2001_6_42_dialog_content = "Isso mesmo, sou o líder deles. Agradeço a todos em Lumópolis por terem cuidado deles pra mim.",
  ui_story_2001_6_43_dialog_content = "Você acha que pode simplesmente ir embora? Sem chance!",
  ui_story_2001_6_44_dialog_content = "Não se preocupe, princesinha. Cuide de seus soldados primeiro. Não fique triste, vamos nos reencontrar quando eu sentir saudades das refeições em Lumópolis.",
  ui_story_2001_6_45_dialog_content = "Pare!",
  ui_story_2001_6_46_dialog_content = "<color=#e8d9bb>Carleen tentou persegui-los, mas, por algum motivo, seus pés pesavam como chumbo e ela só conseguiu ver a gangue da Rediesel Wrench ir embora...</color>",
  ui_story_2001_6_47_dialog_content = "Procurei você em toda parte, Carleen! Você não deve sair correndo se estiver ferida!",
  ui_story_2001_6_48_dialog_content = "O que isso tem a ver com altura, afinal?",
  ui_story_2001_6_49_dialog_content = "Humm? O que você disse?",
  ui_story_2001_6_50_dialog_content = "Nada. Vamos pra casa.",
  ui_story_2001_6_51_dialog_content = "Mas eu prometo, vai ter troco.",
  ui_story_2002_1_1_dialog_content = "...",
  ui_story_2002_1_2_dialog_content = "...Ahn?",
  ui_story_2002_1_3_dialog_content = "Ai! Minha cauda!!",
  ui_story_2002_1_4_dialog_content = "<color=#e8d9bb>A Subcidade permaneceu em silêncio enquanto eles descansavam. Sharona acordou de um sonho com a sensação de que alguém, ou algo, estava tocando sua cauda...</color>",
  ui_story_2002_1_5_dialog_content = "<color=#e8d9bb>A figura de uma pessoa que parecia ser especialista em se esconder se mexia nas sombras.\nPorém, isso convenceu Sharona de que uma pessoa era a responsável por essa brincadeira.</color>",
  ui_story_2002_1_6_dialog_content = "Quem é você, garoto? Como se atreve a tocar minha cauda enquanto estou dormindo?",
  ui_story_2002_1_7_dialog_content = "...",
  ui_story_2002_1_8_dialog_content = "Um Eclipsita? De onde você veio? Aqueles guardas devem estar querendo um treinamento a mais...",
  ui_story_2002_1_9_dialog_content = "Espere... Esse cheiro característico... Posso sentir o cheiro de outra coisa.",
  ui_story_2002_1_10_dialog_content = "Ei! Você é um Eclipsita ou um Aurorian? Vou te dar um minuto pra me responder, então diga algo se me entende!",
  ui_story_2002_1_11_dialog_content = "Por que atacou minha cauda?",
  ui_story_2002_1_12_dialog_content = "Desembucha e talvez eu deixe você viver mais um minuto.",
  ui_story_2002_1_13_dialog_content = "<color=#e8d9bb>A figura permaneceu nas sombras, fazendo ruídos incompreensíveis na escuridão.</color>",
  ui_story_2002_1_14_dialog_content = "Não tem como nos comunicarmos. Você parece mais um Eclipsita pra mim, então não reclame disso...",
  ui_story_2002_1_15_dialog_content = "...hahahahaha...",
  ui_story_2002_1_16_dialog_content = "Vo-você tá rindo? O que você é? Você consegue me entender?",
  ui_story_2002_1_17_dialog_content = "Hahaha... Ahahahaha! Você até que é muito fofa quando está confusa...",
  ui_story_2002_1_18_dialog_content = "Vou querer um presente seu quando nos encontrarmos novamente. Até mais...",
  ui_story_2002_1_19_dialog_content = "Universês?! Espere aí!",
  ui_story_2002_1_20_dialog_content = "Aff! Ele sumiu.",
  ui_story_2002_1_21_dialog_content = "Esse cheiro... parece com a aura de um Eclipsita e... pólvora?",
  ui_story_2002_1_22_dialog_content = "Argh...",
  ui_story_2002_1_23_dialog_content = "Está aqui há muito tempo? Então aquela coisa era sua chefe? Ela realmente deixou seus subordinados morrerem assim? Que piada.",
  ui_story_2002_1_24_dialog_content = "Vou descontar minha frustração em fracotes como você até conseguir achar sua chefe.",
  ui_story_2002_1_25_dialog_content = "Aquelas bombas e Eclipsitas eram tão fracos... Quase não precisei me esforçar com eles.",
  ui_story_2002_1_26_dialog_content = "Sharona? O que faz aqui tão cedo? Que bagunça toda é essa... Você estava brigando com alguém?",
  ui_story_2002_1_27_dialog_content = "Alguns lacaios da escuridão estavam se escondendo do lado de fora, então vim me livrar deles.",
  ui_story_2002_1_28_dialog_content = "Parece que você precisa de ajuda. Que tal um café?",
  ui_story_2002_1_29_dialog_content = "Não se incomode... Pensando bem, vou aceitar.",
  ui_story_2002_1_30_dialog_content = "Isso é raro. Você não deve ter dormido muito bem. Pensei ter ouvido uma explosão enquanto dormia. Tem certeza que tá tudo bem?",
  ui_story_2002_1_31_dialog_content = "Enquanto dormia? Você conseguiu se vestir tão bem assim em tão pouco tempo antes de sair correndo pra ver o que estava acontecendo? Não esperava menos da nossa chefe de gabinete.",
  ui_story_2002_1_32_dialog_content = "Ah? Não esperava por isso. Obrigada pelo elogio. Quer mais açúcar no seu café?",
  ui_story_2002_1_33_dialog_content = "Tanto faz, não me importo. A propósito, você consegue reunir todos aqui?",
  ui_story_2002_1_34_dialog_content = "Ah? Parece algo importante.",
  ui_story_2002_1_35_dialog_content = "Não muito, mas também não é tão simples. Só espero que não dê nada errado.",
  ui_story_2002_1_36_dialog_content = "Mas acabei de ver sua cauda batendo no chão impacientemente. Tem certeza que não é nada sério?",
  ui_story_2002_1_37_dialog_content = "Esquece o que você viu. Eu não quero me repetir.",
  ui_story_2002_1_38_dialog_content = "É só isso. Esse Eclipsita misterioso com certeza vai nos atacar novamente, então devemos estar todos atentos. Pronto. A reunião acabou.",
  ui_story_2002_1_39_dialog_content = "Aff... Tanta gente aqui. Como posso dormir quando a reunião é tão cedo?",
  ui_story_2002_1_40_dialog_content = "Está atrasada, Philyshy.",
  ui_story_2002_1_41_dialog_content = "Não seja ruim! Só dormi um pouco a mais.",
  ui_story_2002_1_42_dialog_content = "Mais cinco minutos? Você quer repetir isso?",
  ui_story_2002_1_43_dialog_content = "Relaxe, senhora! Como dizem, os primeiros cinco minutos de uma reunião são só o aquecimento. Devo ter chegado a tempo das questões mais importantes...",
  ui_story_2002_1_44_dialog_content = "Você... A reunião já acabou.",
  ui_story_2002_1_45_dialog_content = "Ah! Sério? Miau! Não há o que fazer, então. Vou ter que voltar a dormir... Estou com tanto sono...",
  ui_story_2002_1_46_dialog_content = "Vivian, essa é sua subordinada?",
  ui_story_2002_1_47_dialog_content = "O quê?",
  ui_story_2002_1_48_dialog_content = "Essa é sua subordinada?",
  ui_story_2002_1_49_dialog_content = "Ah, hum, sim... ela é...",
  ui_story_2002_1_50_dialog_content = "Você precisa mesmo perguntar? Qual é, senhora, não reconhece seus colegas?",
  ui_story_2002_1_51_dialog_content = "Olhe como fala!",
  ui_story_2002_1_52_dialog_content = "Ah! Vivian está tããão agressiva hoje! Sorria! Vai ficar com rugas se franzir muito a testa, miau.",
  ui_story_2002_1_53_dialog_content = "Eu não sabia que a Illumina tinha um membro tão preguiçoso. Como posso me lembrar de alguém assim? Você deveria refletir por um momento.",
  ui_story_2002_1_54_dialog_content = "Sinto muito... Vou dar uma bronca nela. Não fique brava...",
  ui_story_2002_1_55_dialog_content = "Ei, por que eu deveria levar bronca? Eu só me atrasei um pouquititito de nada...",
  ui_story_2002_1_56_dialog_content = "Isso é ridículo! Você está...",
  ui_story_2002_1_57_dialog_content = "Ah! Já que eu já fiz café, por que não fazemos uma pausa agora e esquecemos essas questões menores?\n...Philyshy, você ficará de patrulha a noite inteira.",
  ui_story_2002_1_58_dialog_content = "O quê!? Isso significa que Philyshy... Isso significa que eu não vou d...",
  ui_story_2002_1_59_dialog_content = "Patrulhará A NOITE INTEIRA! Está me entendendo? Preciso repetir nos seus ouvidos uma terceira vez?!",
  ui_story_2002_1_60_dialog_content = "Tá bem, tá bem, não precisa gritar com Philyshy... Eu vou patrulhar...",
  ui_story_2002_1_61_dialog_content = "Não ligue pra ela, Sharona. Embora Philyshy seja um pouco desleixada, confie no olhar de Reinhardt para o talento. Garanto que ela pode ser muito útil.",
  ui_story_2002_1_62_dialog_content = "Ela é sua subordinada, mas acho que você tem que entender que...",
  ui_story_2002_1_63_dialog_content = "A Illumina não precisa de vagabundos.",
  ui_story_2002_2_1_dialog_content = "...",
  ui_story_2002_2_2_dialog_content = "...Ahn?",
  ui_story_2002_2_3_dialog_content = "Ai! Minha cauda!!",
  ui_story_2002_2_4_dialog_content = "...",
  ui_story_2002_2_5_dialog_content = "Nossa! Você de novo! Se você consegue se infiltrar na Subcidade, por que tá se desgastando tanto só pra atacar minha cauda e...?",
  ui_story_2002_2_6_dialog_content = "O que você realmente quer aqui?",
  ui_story_2002_2_7_dialog_content = "...",
  ui_story_2002_2_8_dialog_content = "Ei, será que você tá transmitindo sinais pra alguém? Pare de conversar com seus colegas Eclipsitas agora. Por que invocar um bando de fracotes pra cá?",
  ui_story_2002_2_9_dialog_content = "A porta tá trancada. Vou te dar um minuto. Explique suas intenções e talvez eu o mate rapidamente.",
  ui_story_2002_2_10_dialog_content = "...hahahaha... Que impaciente!",
  ui_story_2002_2_11_dialog_content = "Eu sabia! Você fala universês... Por que você cheira a Aurorian!? Você é um Aurorian ou... não, com essa aura, você deve ser um Eclipsita.",
  ui_story_2002_2_12_dialog_content = "Apenas deite-se em silêncio e deixe-me levar sua cauda. Não é muito divertido quando você faz isso!",
  ui_story_2002_2_13_dialog_content = "Então você gosta da minha cauda, né? Quê? Vocês Eclipsitas precisam dela pra algo específico?",
  ui_story_2002_2_14_dialog_content = "Só por diversão.",
  ui_story_2002_2_15_dialog_content = "Hã? Mas que... Já que você não quer confessar, terei que capturar e interrogar você!",
  ui_story_2002_2_16_dialog_content = "Hah! Você errou! É porque não tá acordada direito? Vamos nos reencontrar, dragãozinho estúpido.",
  ui_story_2002_2_17_dialog_content = "Estúpido..?! Ei, espera! Aonde você pensa que vai?!",
  ui_story_2002_2_18_dialog_content = "<color=#e8d9bb>Fora da Sala de Inteligência da Illumina</color>",
  ui_story_2002_2_19_dialog_content = "Cadê ela?",
  ui_story_2002_2_20_dialog_content = "Hah! Você é tão pontual. O plano tá indo muuuuuito bem... Ei, falando nisso, o que você queria que eu encontrasse?\nUm forte e poderoso...",
  ui_story_2002_2_21_dialog_content = "Um catalisador explosivo.",
  ui_story_2002_2_22_dialog_content = "Sim, sim, sim, é esse mesmo. Isso e... a cauda do dragãozinho estúpido!",
  ui_story_2002_2_23_dialog_content = "Cauda? Ei, sugiro que seja bom e complete a missão. Você sabe o que acontecerá se surgirem novos problemas, né? A mestra não vai pegar leve com você!",
  ui_story_2002_2_24_dialog_content = "Eu, Bowlinger, sou responsável pela parte mais importante do plano da mestra pra destruir a Illumina. Se não desenvolvermos algo poderoso o bastante até o momento em que atacarmos...",
  ui_story_2002_2_25_dialog_content = "Cof, quase disse algo que não deveria... De qualquer forma, preciso que você encontre um catalisador que possa aumentar muito o dano de ataque!",
  ui_story_2002_2_26_dialog_content = "Sr. Bowlinger, supostamente somos parceiros, então por que não compartilha informações comigo? Tive que fazer um grande esforço para encontrar esse \"núcleo de energia\".",
  ui_story_2002_2_27_dialog_content = "Ahhh! Um núcleo de energia? É a nova tecnologia da Illumina?",
  ui_story_2002_2_28_dialog_content = "Espere, esse é o pacote? É só uma pepita de ouro do tamanho da palma da mão!",
  ui_story_2002_2_29_dialog_content = "Não subestime o pacote! Dentro está um Aparelho Supernúcleo \"Explosão MÁXIMA” com poder ilimitado que eu mesmo experimentei!\nVocê tem que ser extremamente cuidadoso!",
  ui_story_2002_2_30_dialog_content = "Como ele é volátil, lembre-se de não abri-lo a menos que realmente precise usá-lo, pois antes que você perceba, já se foi.",
  ui_story_2002_2_31_dialog_content = "Volátil? Você quer dizer que ele dissipa energia? Ou uma reação ainda mais perigosa?! Estou ficando animado!!",
  ui_story_2002_2_32_dialog_content = "Seja como for, você só precisa confiar em mim. Com isso, Sr. Bowlinger, os preparativos estão completos...",
  ui_story_2002_2_33_dialog_content = "Ótimo! Vou pedir pra alguém vir pegá-lo agora! Não esperava que alguém não muito confiável como você pudesse ajudar.  \nVou falar bem de você para aquela essa pessoa!",
  ui_story_2002_2_34_dialog_content = "Obrigada, Sr. Bowlinger. Lembre-se, não abra esse núcleo de energia até o último instante.",
  ui_story_2002_2_35_dialog_content = "Você tá brincando? Fugiu de novo? Como esses Eclipsitas conseguiram chegar tão perto da gente? Eles pegaram um atalho?",
  ui_story_2002_2_36_dialog_content = "A líder deles deve ser a responsável por isso. Ela enviou um grupo de Eclipsitas fracotes pra cá pra morrer de propósito...",
  ui_story_2002_2_37_dialog_content = "Ela tá tentando me atrair pra longe daqui?! Se o objetivo deles é me atrair pra longe da entrada da Subcidade,",
  ui_story_2002_2_38_dialog_content = "quer dizer que seu verdadeiro alvo é... O lugar mais próximo é o Departamento de Inteligência, e só quem tá de serviço noturno é...",
  ui_story_2002_2_39_dialog_content = "Philyshy!!",
  ui_story_2002_2_40_dialog_content = "Ufa... Está tão silencioso aqui. Parece que nada aconteceu ainda.",
  ui_story_2002_2_41_dialog_content = "<color=#e8d9bb>Porém, uma figura familiar e vestida de branco estava encostada na porta aberta da sala da inteligência e parecia estar inconsciente.</color>",
  ui_story_2002_2_42_dialog_content = "P-Philyshy! Você tá bem?! Será que ela foi atacada?",
  ui_story_2002_2_43_dialog_content = "Chamem os médicos!!",
  ui_story_2002_2_44_dialog_content = "Você estava apenas dormindo?",
  ui_story_2002_2_45_dialog_content = "Philyshy... Philyshy estava com muito sono... De jeito nenhum a senhora vai me dizer que é contra a lei dormir...",
  ui_story_2002_2_46_dialog_content = "Se você não foi atacada, por que a porta da sala de inteligência estava aberta daquele jeito?",
  ui_story_2002_2_47_dialog_content = "Humm... Philyshy não faz ideia...",
  ui_story_2002_2_48_dialog_content = "De qualquer maneira, deixe-me ver se você está ferida.",
  ui_story_2002_2_49_dialog_content = "Não se preocupe. Ela tá bem. Ela supostamente é um gato, mas dorme como um...",
  ui_story_2002_2_50_dialog_content = "Vivian, você encontrou a pessoa que descrevi? Deve haver um atalho escondido que o inimigo está usando pra ocultar sua operação.",
  ui_story_2002_2_51_dialog_content = "Não tenho nenhuma pista. Se o Eclipsita conseguiu escapar de você, não acho que soldados comuns tenham alguma chance.",
  ui_story_2002_2_52_dialog_content = "O que será que ele quer... Ele só bagunçou a cozinha do Departamento de Inteligência. Parece que não sumiu nada,\ne Philyshy também não se machucou.",
  ui_story_2002_2_53_dialog_content = "Não sei. A pessoa que vi era simplesmente inexplicável... Não sei o que achar disso.",
  ui_story_2002_2_54_dialog_content = "Desculpe, eu tava com muito sono, então eu... dormi...",
  ui_story_2002_2_55_dialog_content = "Não tínhamos intenção de culpar você, mas você... deveria ao menos levar suas desculpas mais a sério.",
  ui_story_2002_2_56_dialog_content = "Qual é, só tirei uma soneca... Você deveria saber que eu não consigo ficar acordada quando estou sonolenta,\ne eu fui dormir tarde ontem.",
  ui_story_2002_2_57_dialog_content = "Então, a sala de inteligência foi invadida porque você tava dormindo? O inimigo foi capaz de entrar facilmente assim?\nNem Reinhardt ficaria do seu lado, se ela soubesse disso.",
  ui_story_2002_2_58_dialog_content = "Hum... Sharona, acabei de entrar em contato com Reinhardt, e ela tem algumas ordens.",
  ui_story_2002_2_59_dialog_content = "Ela ficou nervosa?! É-é tudo culpa minha... Isso não teria acontecido se eu tivesse conseguido pegar aquela criatura... Eu falhei com meu dever.",
  ui_story_2002_2_60_dialog_content = "Não se preocupe, ela não tá brava. Ela falou pra continuarmos investigando o que desapareceu e qual é o propósito do inimigo.",
  ui_story_2002_2_61_dialog_content = "Vou fazer alguns interrogatórios internos junto com ela, mas você precisa continuar com as investigações externas.",
  ui_story_2002_2_62_dialog_content = "Entendi. Diga a ela que pode ficar tranquila e confiar esse assunto a mim.",
  ui_story_2002_2_63_dialog_content = "Além disso, ela gostaria que você tivesse um assistente.",
  ui_story_2002_2_64_dialog_content = "Um assistente? Não, ela sabe que consigo resolver isso sozinha. Por que ela...",
  ui_story_2002_2_65_dialog_content = "Não fale isso em um momento como este, Sharona. Se o inimigo for muito poderoso...",
  ui_story_2002_2_66_dialog_content = "Mas você sabe que é pior se alguém ficar no meu caminho.",
  ui_story_2002_2_67_dialog_content = "Na verdade, ela já indicou alguém.",
  ui_story_2002_2_68_dialog_content = "<color=#e8d9bb>Vivian olhou para Philyshy, que ainda estava sonolenta, com uma expressão intrigada. Philyshy congelou por um momento antes de voltar a si.</color>",
  ui_story_2002_2_69_dialog_content = "...Hã? A chefe quer que eu vá??",
  ui_story_2002_2_70_dialog_content = "Sim, você precisa ir com Sharona e investigar tudo. Faça isso e você não será punida pelo que aconteceu hoje.",
  ui_story_2002_2_71_dialog_content = "<color=#e8d9bb>Sharona e Philyshy ficaram em silêncio após ouvirem isso. Elas olharam uma para a outra, mas não disseram uma palavra...</color>",
  ui_story_2002_3_1_dialog_content = "Sharona... não, a partir de agora devo te chamar de líder, miau! Você tá brava?",
  ui_story_2002_3_2_dialog_content = "Líder, não fique brava... prometo que vou te ajudar! Líder, você é tão forte!\nFarei o meu melhor pra ser também!",
  ui_story_2002_3_3_dialog_content = "Ah! É tão assustador aqui! Líder, pode ficar perto de mim?",
  ui_story_2002_3_4_dialog_content = "Líder, como você ficou tão forte sem parecer muito musculosa? Você treina os seus músculos de uma maneira especial?",
  ui_story_2002_3_5_dialog_content = "Líder! Seus chifres e sua cauda são muito especiais! Posso tocá-los? Posso? Posso?",
  ui_story_2002_3_6_dialog_content = "Silêncio! Você é muito barulhenta.",
  ui_story_2002_3_7_dialog_content = "Por que tá tão chateada comigo? Por que tá correndo tão rápido? Eu não consigo acompanhar! Devagar!",
  ui_story_2002_3_8_dialog_content = "Você não sente nenhum remorso? Isso não teria acontecido se você não tivesse dormido em serviço.",
  ui_story_2002_3_9_dialog_content = "Miau? Desculpe, mas eu tava com muito sono hoje e não consegui ficar acordada de jeito nenhum. Além do mais, temos a chance de consertar as coisas!\nPhilyshy não sabe de nada...",
  ui_story_2002_3_10_dialog_content = "Ah não, tô sentindo sono de novo...",
  ui_story_2002_3_11_dialog_content = "Inútil.",
  ui_story_2002_3_12_dialog_content = "Hã? O que é isso?",
  ui_story_2002_3_13_dialog_content = "<color=#e8d9bb>Algo chamou a atenção de Philyshy. Ela caminhou sozinha em direção a uma bifurcação</color>",
  ui_story_2002_3_16_dialog_content = "É um inimigo? Hum, não, não é bem isso... Eu me enganei?",
  ui_story_2002_3_17_dialog_content = "Achei que tivesse sentido algo, mas a aura desapareceu...",
  ui_story_2002_3_18_dialog_content = "Não há mais caminho à frente... Ei, Philyshy, nós...",
  ui_story_2002_3_19_dialog_content = "Philyshy?",
  ui_story_2002_3_20_dialog_content = "Ela se foi? Eu sabia que não devia tê-la trazido junto!",
  ui_story_2002_3_21_dialog_content = "Droga... Agora tenho que salvá-la antes de completar a missão. Reinhardt com certeza vai ficar irritada comigo se eu a deixar sozinha...\nAff! Que dor de cabeça!",
  ui_story_2002_3_22_dialog_content = "Ei! Eu ouvi tudo, miau! Você disse que me salvaria antes de completar a missão...",
  ui_story_2002_3_23_dialog_content = "Você?! Pra onde você foi?",
  ui_story_2002_3_24_dialog_content = "Também não sei. Encontrei uma entrada esquisita! Parece levar a um lugar estranho.\nVamos continuar por aqui!",
  ui_story_2002_3_25_dialog_content = "Como eu esperava, há um atalho... Como você o encontrou?",
  ui_story_2002_3_26_dialog_content = "Talvez seja intuição felina? Sobretudo, líder, tô muito comovida com o que você disse, que me salvaria primeiro...",
  ui_story_2002_3_27_dialog_content = "Eu não disse isso. Esqueça. Vamos seguir em frente e nos preparar pra lutar!",
  ui_story_2002_3_28_dialog_content = "Hehe, você simplesmente não consegue ser honesta consigo mesma, miau.",
  ui_story_2002_3_29_dialog_content = "Hã?! Esse atalho fica tão perto da Subcidade! Parece uma base secreta! A propósito, líder, você cavava buracos quando era criança?\nPor exemplo...",
  ui_story_2002_3_30_dialog_content = "Quieta! Isso não é brincadeira, então fique atenta!",
  ui_story_2002_3_31_dialog_content = "Ah! A líder é tão rígida, miau...",
  ui_story_2002_3_32_dialog_content = "Tem menos inimigos do que eu esperava. Devo ter matado a maioria deles ontem.",
  ui_story_2002_3_33_dialog_content = "Ah! Líder, cuidado!",
  ui_story_2002_3_34_dialog_content = "!!!",
  ui_story_2002_3_35_dialog_content = "<color=#e8d9bb>Sharona sacou sua lâmina, cortando seu oponente em dois no ar. Ele não teve a menor chance.</color>",
  ui_story_2002_3_36_dialog_content = "Humf, você acha que eu não percebi o ataque? Eu já tinha puxado minha lâmina enquanto você falava, sua inútil...",
  ui_story_2002_3_37_dialog_content = "<color=#e8d9bb>Sharona se virou e reparou que aquele era apenas um de dois Eclipsitas, e Philyshy havia derrotado o outro.</color>",
  ui_story_2002_3_38_dialog_content = "Você...!",
  ui_story_2002_3_39_dialog_content = "Ah? Líder, me desculpe. Eu sabia que você poderia resolver tudo, miau... Mas tinha mais um atrás de você, então eu ajudei.",
  ui_story_2002_3_40_dialog_content = "Eu não preciso da sua ajuda. Você só precisa se proteger.",
  ui_story_2002_3_41_dialog_content = "Tenha cuidado com você mesma, e não comigo... Eu não quero que você me atrase!",
  ui_story_2002_3_42_dialog_content = "Mas... cof, obrigada.",
  ui_story_2002_3_43_dialog_content = "(Ela me salvou, mas eu quase a interpretei errado... Parece que não sou forte o bastante. Tenho que me tornar forte o bastante pra resolver tudo sozinha...)",
  ui_story_2002_3_45_dialog_content = "Ah, er, eu não tenho nenhum outro propósito... Eu só...",
  ui_story_2002_3_46_dialog_content = "Fale mais baixo... Vamos seguir em frente.",
  ui_story_2002_3_47_dialog_content = "Tudo bem. Philyshy está cansada e com sono... Você pode ir um pouco mais devagar?",
  ui_story_2002_4_1_dialog_content = "(Este atalho é bastante extenso, mas parece não levar a nenhum lugar importante e não é fácil marchar aqui. Pra que será que é usado?)",
  ui_story_2002_4_2_dialog_content = "Ei, Philyshy, a gente deve enfrentar alguns inimigos fortes em breve. Tome cuidado e se esconda, se puder.",
  ui_story_2002_4_3_dialog_content = "Acho que sua espadinha não será suficiente para um embate frontal... Ei, está me ouvindo?",
  ui_story_2002_4_4_dialog_content = "Líder, me desculpe... tô tão cansada... com tanto sono, miau...",
  ui_story_2002_4_5_dialog_content = "O quê? Com sono? Agora?! Você tá brincando? Fique acordada!",
  ui_story_2002_4_6_dialog_content = "Ah, mas eu tô com tanto sono... Philyshy quer tirar uma soneca. Que tal uma soneca rapidinha...",
  ui_story_2002_4_7_dialog_content = "Isso parece um lugar pra dormir?! Não me atrapalhe, mesmo que queira morrer! Eu não vou te proteger!",
  ui_story_2002_4_8_dialog_content = "Vai sim... Você é durona...",
  ui_story_2002_4_9_dialog_content = "Mas você é... muito... *roncando*",
  ui_story_2002_4_10_dialog_content = "Não acredito...! Você já não dormiu a noite inteira? Como você consegue cair no sono assim?!",
  ui_story_2002_4_11_dialog_content = "Aff, ela já dormiu.",
  ui_story_2002_4_12_dialog_content = "“Quando um membro fraco da equipe é negligente, é geralmente quando há a maior chance do inimigo surgir.”",
  ui_story_2002_4_13_dialog_content = "Aaaargh...!",
  ui_story_2002_4_14_dialog_content = "Claro que sei. Só canalhas atacam alguém vulnerável. Encoste nela por sua própria conta e risco.",
  ui_story_2002_4_15_dialog_content = "Uma batalha desse nível... Você tá jogando bola? Que coincidência. Além de lutar, isso é o que faço de melhor.",
  ui_story_2002_4_16_dialog_content = "Ei, você! Por que ainda não acordou?",
  ui_story_2002_4_17_dialog_content = "Ugh... Como ela pode dormir tão tranquilamente? Desde quando a Illumina tem um membro como ela...",
  ui_story_2002_4_18_dialog_content = "(Tsc, o jeito que ela tá dormindo me lembra algo... será que a irmãzona olha pra mim da mesma forma quando eu durmo?)",
  ui_story_2002_4_19_dialog_content = "(Como ela pode se sentir tão segura largando sua segurança nas mãos de outra pessoa? Ela faz isso por confiança?)",
  ui_story_2002_4_20_dialog_content = "(Mas parecia muito seguro naquele momento.)",
  ui_story_2002_4_21_dialog_content = "Não, eu não sou igual a ela! Levante! Agora!",
  ui_story_2002_4_22_dialog_content = "Eu... Eu não posso continuar... Ainda tô com tanto sono...",
  ui_story_2002_4_23_dialog_content = "Você não dormiu o suficiente essa noite? Nossa... Você tá de brincadeira? Você tá dormindo de novo?!",
  ui_story_2002_5_1_dialog_content = "Então você estava aqui, dragão estúpido.",
  ui_story_2002_5_2_dialog_content = "Hum? Você tá acordada?",
  ui_story_2002_5_3_dialog_content = "Estou tomando conta de você há... Espera, do que você acabou de me chamar?",
  ui_story_2002_5_4_dialog_content = "Hahaha! Você parece muito acostumada comigo te chamando assim! Sentiu falta de mim?",
  ui_story_2002_5_5_dialog_content = "Philyshy? Pare de brincadeira. Você tá confusa de tanto dormir? Venha aqui.",
  ui_story_2002_5_6_dialog_content = "Heh, você já se esqueceu de mim? Hahaha! Tô muito feliz de encontrá-la pela terceira vez, miau.",
  ui_story_2002_5_7_dialog_content = "É você?! Você soa e cheira diferente... Você é aquela criatura?!",
  ui_story_2002_5_8_dialog_content = "Hehe, você demorou bastante pra perceber! Já era esperado de alguém que tá ficando velha!",
  ui_story_2002_5_9_dialog_content = "<color=#e8d9bb>O olhar de Sharona se tornou frio enquanto sua mão direita instintivamente pegava no cabo de sua lâmina. A pessoa à sua frente não era mais Philyshy.\nEla tinha certeza disso.</color>",
  ui_story_2002_5_10_dialog_content = "Quem é você? Se fizer algo suspeito, não reclame se eu te atacar!",
  ui_story_2002_5_11_dialog_content = "Por que não tenta adivinhar?",
  ui_story_2002_5_12_dialog_content = "Você é o demônio ardiloso que queria me matar enquanto eu dormia.",
  ui_story_2002_5_13_dialog_content = "Ahahahahaha! Matar? Eu tava só terminando minha missão e quis a sua cauda. A propósito, pode me chamar de Yumi.",
  ui_story_2002_5_14_dialog_content = "Por que você tá no corpo da Philyshy? Saia!",
  ui_story_2002_5_15_dialog_content = "Philyshy? O quê? Não tô possuindo nada nem o corpo de ninguém.",
  ui_story_2002_5_16_dialog_content = "Este corpo, na verdade, pertence a mim.",
  ui_story_2002_5_17_dialog_content = "Hã? Então o seu jeito de sempre é só um disfarce? Você se escondeu na escuridão por tanto tempo só pra trabalhar para os Eclipsitas?",
  ui_story_2002_5_18_dialog_content = "Disfarce? Hahahaha! Não, não, não, não tem nada disso, miau!",
  ui_story_2002_5_19_dialog_content = "Vá direto ao ponto e seja honesta comigo! Não reclame se eu for impiedosa com você por ficar de brincadeira comigo!",
  ui_story_2002_5_20_dialog_content = "Impiedosa? Por que não experimenta me atacar então, dragão estúpido!",
  ui_story_2002_5_21_dialog_content = "Hahaha! Nada mal, seu dragão estúpido! Miau!",
  ui_story_2002_5_22_dialog_content = "Você é a única que restou. Não se esconda, senão vou virar esse lugar do avesso pra pegar você!",
  ui_story_2002_5_23_dialog_content = "Hah! Estou ansiosa por isso! Miau!",
  ui_story_2002_5_24_dialog_content = "Tsc...",
  ui_story_2002_5_25_dialog_content = "Não vai vir me pegar?",
  ui_story_2002_5_26_dialog_content = "(Tudo vai terminar assim que eu acabar com ela. Ela causou um desastre tão grande... e ainda me fez de idiota!)",
  ui_story_2002_5_27_dialog_content = "Você tá cansada? Quer tirar uma soneca?",
  ui_story_2002_5_28_dialog_content = "Cale a boca...",
  ui_story_2002_5_29_dialog_content = "(Será necessário apenas um golpe do ombro esquerdo ao abdômen direito... posso derrotá-la instantaneamente dessa distância...)",
  ui_story_2002_5_30_dialog_content = "A forma como Philyshy fala e se comporta me dá a sensação de ela ser duas pessoas distintas,",
  ui_story_2002_5_31_dialog_content = "mas não só isso. Reparei algumas vezes que ela parece ser capaz de se comunicar com os Eclipsitas.",
  ui_story_2002_5_32_dialog_content = "Vivian, você tá vendo coisa demais aqui. Pode ser só uma falha de personalidade. Dizem que também sou assustadora em batalha...",
  ui_story_2002_5_33_dialog_content = "Também espero que seja apenas um transtorno de personalidade, mas acho que não é tão simples.",
  ui_story_2002_5_34_dialog_content = "Além disso, uma Aurorian se comunicando com os Eclipsitas? Isso é ridículo. Achei que tinha eliminado todos eles durante a guerra.",
  ui_story_2002_5_35_dialog_content = "É verdade, Reinhardt me contou pessoalmente. Tenho medo que Philyshy faça algo que prejudique a Illumina, mesmo sem perceber, e depois se arrependa de suas ações.",
  ui_story_2002_5_36_dialog_content = "Bem, se ela se atrever,",
  ui_story_2002_5_37_dialog_content = "acabo com ela sem qualquer hesitação.",
  ui_story_2002_5_38_dialog_content = "(Mas por que... por que não consigo atacá-la?)",
  ui_story_2002_5_39_dialog_content = "(Por que... Só preciso mover minha lâmina... Droga, vai logo, Sharona!)",
  ui_story_2002_5_40_dialog_content = "Líder, não fique brava... prometo que vou te ajudar! Líder, você é tão forte!\nFarei o meu melhor pra ser também!",
  ui_story_2002_5_41_dialog_content = "Você vai me proteger... Você é durona... Mas você é... muito... *roncando*",
  ui_story_2002_5_42_dialog_content = "...*Arf, arf*...",
  ui_story_2002_5_43_dialog_content = "(Se Reinhardt tiver planejado tudo isso de propósito sabendo que eu não conseguiria matá-la... O que devo fazer...)",
  ui_story_2002_5_44_dialog_content = "...",
  ui_story_2002_5_45_dialog_content = "...Ahn?",
  ui_story_2002_5_46_dialog_content = "“Cauda”...",
  ui_story_2002_5_47_dialog_content = "Eu sei!",
  ui_story_2002_5_48_dialog_content = "(Fazer algo assim de verdade... Não! Isso é apenas uma tática! Devo fazer o que preciso fazer!)",
  ui_story_2002_5_49_dialog_content = "<color=#e8d9bb>Sharona respirou fundo e rapidamente lançou sua cauda pra frente.</color>",
  ui_story_2002_5_50_dialog_content = "Você não queria minha cauda? Vamos lá, vem pegar, me capture e ela será sua.",
  ui_story_2002_5_51_dialog_content = "Miau! O-o quê???",
  ui_story_2002_5_52_dialog_content = "Minha cauda ágil e divertida está bem na sua frente! Você não quer?!",
  ui_story_2002_5_53_dialog_content = "(Nossa, o que eu tô fazendo?!)",
  ui_story_2002_5_54_dialog_content = "Droga! Como você ousa! Você realmente... arghhh! Miau!",
  ui_story_2002_5_55_dialog_content = "<color=#e8d9bb>Yumi pulou pra pegar a cauda de Sharona, que se afastou agilmente, levando sua cauda para o outro lado do corpo enquanto se movia em direção a sua oponente.</color>",
  ui_story_2002_5_56_dialog_content = "Anzol, linha e chumbada... Aqui!",
  ui_story_2002_5_57_dialog_content = "Eu te peguei!",
  ui_story_2002_5_58_dialog_content = "Miiiiaaaau!!!!!!",
  ui_story_2002_5_59_dialog_content = "O que... onde estou... hã? Líder?",
  ui_story_2002_5_60_dialog_content = "Parece que você voltou ao normal... Sua gata boba, você desperdiçou muito o meu tempo.",
  ui_story_2002_5_61_dialog_content = "O-o que aconteceu?",
  ui_story_2002_5_62_dialog_content = "Não aconteceu nada. Não faça perguntas.",
  ui_story_2002_5_63_dialog_content = "Ah!!! Ah não!!! Eu me lembro agora!!!",
  ui_story_2002_5_64_dialog_content = "Lembra de quê?! Você não pode contar pra ninguém!!",
  ui_story_2002_5_65_dialog_content = "Hã? O que foi? Acabei de me lembrar do que desapareceu.",
  ui_story_2002_5_66_dialog_content = "Ah? Hum, e aí... o que foi?",
  ui_story_2002_5_67_dialog_content = "Não, pra ser mais exata, o certo é dizer o que a Yumi pegou...",
  ui_story_2002_5_68_dialog_content = "Sua idiota! Não me diga que você sabia... Por que não me contou? Não é um pouco tarde pra você lembrar?!",
  ui_story_2002_5_69_dialog_content = "Hã? Eu geralmente troco com ela quando estou dormindo, e é fácil esquecer... Desculpe, miau...",
  ui_story_2002_5_70_dialog_content = "Lembro que era algo muito importante. Era dourado, brilhante e do tamanho da palma da mão. É muito poderoso!\nÉ um tesouro com o qual todos nos importamos!",
  ui_story_2002_5_71_dialog_content = "Yumi deu pra alguém que eu não conheço... Não, nós nos conhecíamos, mas eu não sei dizer quem era...\nParece um sonho que não consigo me lembrar...",
  ui_story_2002_5_72_dialog_content = "Esqueça. Seja o que for, pegarei de volta em breve. Quanto a você, é bom que até chore de tanto pedir desculpas quando voltarmos! Enfim...\nQuem é Yumi?",
  ui_story_2002_5_73_dialog_content = "Ela é minha gata. Já foi minha parceira, mas agora é uma segunda versão de mim.",
  ui_story_2002_5_74_dialog_content = "Como você mesma viu, não sou muito forte, mas fico muito mais forte quando estou com Yumi.\nEra assim no passado e agora também.",
  ui_story_2002_5_75_dialog_content = "Mas é provável que Yumi não esteja mais aqui. Talvez ela viva no coração de Philyshy, representando minhas saudades por ela.",
  ui_story_2002_5_76_dialog_content = "Talvez esses sentimentos sejam fortes demais e acabo fazendo coisas estranhas, às vezes... Talvez deva ir ao médico.",
  ui_story_2002_5_77_dialog_content = "Após essa missão, vou te contar tudo sobre meu passado, tá bom? Tenho muitas histórias interessantes pra contar!",
  ui_story_2002_5_78_dialog_content = "Você... é sempre tão difícil de entender. Enfim, por que você me atacou com o Eclipsita quando tava naquele estado?\nParecia que tinha se voltado contra nós...",
  ui_story_2002_5_79_dialog_content = "Ah... Foi tão sério assim? Sinto muito que Yumi tenha causado problemas, líder. Por favor, perdoe ela.",
  ui_story_2002_5_80_dialog_content = "Ela também não consegue evitar... É como se tivesse uma voz na minha cabeça mandando a gente fazer coisas. Pensando nisso, pode ser...",
  ui_story_2002_5_81_dialog_content = "a voz maligna de uma mulher.",
  ui_story_2002_6_1_dialog_content = "O atalho acaba aqui. A pessoa que tem manipulado você provavelmente tá atrás dessa porta...",
  ui_story_2002_6_2_dialog_content = "Philyshy! Como está se sentindo? Por que você não espera por mim aqui? Eu posso...",
  ui_story_2002_6_3_dialog_content = "Ei! Não precisa ser superprotetora! Já me recuperei completamente!",
  ui_story_2002_6_4_dialog_content = "Que bom. Quando escaparmos daqui, vou precisar que você me dê uma explicação mais detalhada... Temos coisas mais importantes pra fazer agora.",
  ui_story_2002_6_5_dialog_content = "Líder, existe uma aura estranha do lado de dentro...",
  ui_story_2002_6_6_dialog_content = "É bastante evidente. O fedor dos Eclipsitas é tão forte que me faz passar mal.",
  ui_story_2002_6_7_dialog_content = "Fique atenta! Vou abrir a porta!",
  ui_story_2002_6_8_dialog_content = "Sim, senhora!",
  ui_story_2002_6_9_dialog_content = "Bem-vindas ao Instituto de Grandes Armas, a maior criação do mestre, o grande e inteligente Bowlinger, com quem vocês estão falando agora!",
  ui_story_2002_6_10_dialog_content = "Em que posso ajudar?",
  ui_story_2002_6_11_dialog_content = "Por gentileza, seja uma pessoa distinta e morra imediatamente!",
  ui_story_2002_6_12_dialog_content = "Não entendi muito bem. Eu preferiria que você tivesse me perguntado isso:",
  ui_story_2002_6_13_dialog_content = "\"Bowlinger, você pode me matar?\"",
  ui_story_2002_6_14_dialog_content = "É claro! Vou preparar um grande funeral pra você imediatamente!!",
  ui_story_2002_6_15_dialog_content = "Ah! Líder, eu me lembro agora!",
  ui_story_2002_6_16_dialog_content = "Muitas pessoas estão curiosas pra saber o que a fofinha Philyshy lembra. Bem, do que Philyshy se lembra?",
  ui_story_2002_6_17_dialog_content = "Deixe o incrível Bowlinger contar a todos o que Philyshy lembra. Isso com certeza é uma grande questão.",
  ui_story_2002_6_18_dialog_content = "E isso é tudo sobre o que Philyshy lembra. Se tiver interesse em saber o que Philyshy lembra,\nvocê também pode...",
  ui_story_2002_6_19_dialog_content = "Cale a boca! Fique quieto!!",
  ui_story_2002_6_20_dialog_content = "Aquela coisa importante! Foi dada a esse... esse rato!",
  ui_story_2002_6_21_dialog_content = "Você... você realmente sabe como me poupar tempo.",
  ui_story_2002_6_22_dialog_content = "Rato? Como se atreve a me insultar, o grande e fascinante Bowlinger!\nVou explodir vocês até que se tornem apenas um átomo!",
  ui_story_2002_6_23_dialog_content = "Cof, vocês são poderosas demais e nem mesmo eu consigo não admirá-las.",
  ui_story_2002_6_24_dialog_content = "No entanto, com o apoio da Srta. Philyshy, tenho a chance de perguntar algo muito importante! Srta. Sharona,",
  ui_story_2002_6_25_dialog_content = "você sabe o que é isso? Ah! O inteligente Bowlinger aproveitou a oportunidade de responder a essa pergunta! A resposta é: o núcleo do novo sistema de energia da Illumina!\nÉ um poderoso catalisador!!",
  ui_story_2002_6_26_dialog_content = "Se eu usá-lo, toda a Illumina será destruída em pedaços!! Vocês duas, nem se fala.",
  ui_story_2002_6_27_dialog_content = "Inicialmente, a mestra queria que eu cavasse um túnel abaixo da Subcidade e colocasse pólvora suficiente pra destruir suas fundações\nem preparação para o dia em que ela atacasse a Illumina!",
  ui_story_2002_6_28_dialog_content = "Mas encontrei um gargalo em minha pesquisa de surpresa. Quase não consegui desenvolver minha arma suprema pra perfurar o sistema de defesa de Gannon!",
  ui_story_2002_6_29_dialog_content = "Hehe! Mas graças à Srta. Philyshy, finalmente consegui! Sua persona Yumi me deu exatamente o catalisador que eu precisava!",
  ui_story_2002_6_30_dialog_content = "...isso...",
  ui_story_2002_6_31_dialog_content = "\"Foi usado Fluxo Escuro pra modificar Yumi e realizar experimentos pra fundi-la com Philyshy. Na terapia de trauma psicológico.\"",
  ui_story_2002_6_32_dialog_content = "“Aproveitamos a baixa força de vontade dos animais pra manipular Philyshy. É necessária mais observação... Risco: Alto.\"",
  ui_story_2002_6_33_dialog_content = "Um plano tão engenhoso só pode ter sido arquitetado pela grande... Cof! Quase falei demais na minha empolgação!!",
  ui_story_2002_6_34_dialog_content = "Sinto muito, líder... eu...",
  ui_story_2002_6_35_dialog_content = "Silêncio. Não consigo controlar minha raiva agora.",
  ui_story_2002_6_36_dialog_content = "É tudo culpa da Philyshy... É porque eu...",
  ui_story_2002_6_37_dialog_content = "Seu lixo! Como você ousa usar minha amiga assim!",
  ui_story_2002_6_38_dialog_content = "Hã? Hã? A-amiga?",
  ui_story_2002_6_39_dialog_content = "Sim, vocês são tão amigas! Acho que vou até matar os seus outros amigos da Illumina depois de me livrar de vocês duas!",
  ui_story_2002_6_40_dialog_content = "Já que vocês, ratinhas, tiveram a sorte de descobrir o plano da mestra antes da hora,\ntalvez eu deva adiantar a destruição de Gannon e oferecê-la para a mestra.",
  ui_story_2002_6_41_dialog_content = "<color=#e8d9bb>Bowlinger inseriu rapidamente o dispositivo dourado dado a ele por Yumi na base do reator e ligou a energia.</color>",
  ui_story_2002_6_44_dialog_content = "O núcleo foi inserido! Meu dispositivo extremamente poderoso foi ativado! Observe sua cor única e seu formato delicado!",
  ui_story_2002_6_45_dialog_content = "Ele é tão deslumbrante e tem uma textura tão maravilhosa!",
  ui_story_2002_6_46_dialog_content = "Ele também tem um... um... um cheiro que atrai...",
  ui_story_2002_6_47_dialog_content = "Por que está me impedindo de atacá-lo? Você acha que devemos apenas ficar aqui paradas e esperar que ele nos mate, Philyshy?",
  ui_story_2002_6_48_dialog_content = "Não! Você não tá sentindo o cheiro, líder?",
  ui_story_2002_6_49_dialog_content = "De fato é um cheiro... cof...  podre... O núcleo de energia fede tanto assim?",
  ui_story_2002_6_50_dialog_content = "Isso é... Hã? Peixe enlatado?",
  ui_story_2002_6_51_dialog_content = "Ah... eu me lembro agora. Yumi levou uma lata de peixe com ela.",
  ui_story_2002_6_52_dialog_content = "Então, a coisa muito importante que você mencionou antes... é o peixe enlatado?",
  ui_story_2002_6_53_dialog_content = "Não é um peixe enlatado qualquer! Reinhardt o trouxe de Northland! É uma lata de arenque muito rara!",
  ui_story_2002_6_54_dialog_content = "Tudo bem, entendi... Vejo que você é um gato.",
  ui_story_2002_6_55_dialog_content = "Líder, pode pegar a lata de volta pra mim? Vou falar pra Yumi parar de tentar roubar sua cauda o tempo todo.",
  ui_story_2002_6_56_dialog_content = "P-p-peixe enlatado?!!! Mentirosa! Bah! Ugh! Como ousa!!",
  ui_story_2002_6_57_dialog_content = "Como ousa tirar sarro de mim assim!! Vocês... ugh... JÁ ERAM!! Como isso pode cheirar tão mal???",
  ui_story_2002_6_58_dialog_content = "Mesmo que o núcleo seja falso, o plano ainda não fracassou completamente!\nAo menos vou explodir este lugar em pedaços! Morram!!",
  ui_story_2002_6_59_dialog_content = "Vou ativar o comando de autodestruição! Iniciar contagem regressiva de 10 segundos!!",
  ui_story_2002_6_60_dialog_content = "Corra, líder!!",
  ui_story_2002_6_61_dialog_content = "Pra que a pressa? Ele não disse que temos 10 segundos?",
  ui_story_2002_6_62_dialog_content = "Depressa!",
  ui_story_2002_6_63_dialog_content = "<color=#e8d9bb>6, 5,</color>",
  ui_story_2002_6_64_dialog_content = "Estou procurando a sua lata... Pare de gritar! Ugh... esse cheiro!!",
  ui_story_2002_6_65_dialog_content = "<color=#e8d9bb>4,</color>",
  ui_story_2002_6_66_dialog_content = "Peguei. Dê sua mão. Vamos embora agora!",
  ui_story_2002_6_67_dialog_content = "<color=#e8d9bb>3, 2,</color>",
  ui_story_2002_6_68_dialog_content = "Ah! Eu tô caindo!",
  ui_story_2002_6_69_dialog_content = "Nossa, você é um porre, hein, gatinha!!",
  ui_story_2002_6_70_dialog_content = "<color=#e8d9bb>1!</color>",
  ui_story_2002_6_71_dialog_content = "<color=#e8d9bb>No fim do atalho, um clarão e uma rajada de ar as alcançaram imediatamente, seguido por um estrondo ensurdecedor.</color>",
  ui_story_2002_6_73_dialog_content = "Desculpe... É tudo culpa minha...",
  ui_story_2002_6_74_dialog_content = "Eu era um risco desde o início, e algo ruim realmente aconteceu! Buá! Até o pelo da minha cauda ficou frisado com o calor!",
  ui_story_2002_6_75_dialog_content = "Não é hora para as suas besteiras, sua idiota! Minha cauda também tá torrando!",
  ui_story_2002_6_76_dialog_content = "Seja o que for, se estiver realmente preocupada com o seu problema, vou encontrar uma maneira de curá-la! Se repetir o que disse, vou acertar sua cabecinha felina com a minha espada!",
  ui_story_2002_6_77_dialog_content = "Sinto muito! Estou começando a ficar sonolenta de novo... Líder, quero dormir... Posso... tirar um...",
  ui_story_2002_6_79_dialog_content = "Você vai dormir mesmo que eu a proíba! Faça o que quiser!",
  ui_story_2002_6_X1_dialog_content = "Vou continuar te protegendo...",
  ui_story_2002_6_80_dialog_content = "<color=#e8d9bb>Depois que o fogo se extinguiu, uma figura misteriosa apareceu entre as ruínas na área central da explosão.</color>",
  ui_story_2002_6_81_dialog_content = "Bowlinger? Esta situação deplorável é o \"plano infalível\" que você me prometeu?",
  ui_story_2002_6_82_dialog_content = "<color=#e8d9bb>Enquanto isso, o moribundo Bowlinger continuava caído nas ruínas, sem forças para nada.</color>",
  ui_story_2002_6_83_dialog_content = "\"Aquele item\" era peixe enlatado... Gatos são muito imprevisíveis, eu não devia ter esperado muito deles.",
  ui_story_2002_6_84_dialog_content = "Schummer é muito mais confiável. Claro, é muito precipitado tentar destruir a sede da Illumina...\nPelo menos nós tentamos.",
  ui_story_2002_6_85_dialog_content = "Bowlinger.",
  ui_story_2002_6_86_dialog_content = "Sim... cof...",
  ui_story_2002_6_87_dialog_content = "Você é mais inútil do que um gato.",
  ui_story_2002_6_88_dialog_content = "Mas tudo virou fumaça, graças a você. Imagino que ninguém saiba sobre este... infortúnio.",
  ui_story_2002_6_89_dialog_content = "Mestra, eu... eu vou...",
  ui_story_2002_6_90_dialog_content = "Não precisa se culpar. Existem diversos seguidores em Eclipse e seus compatriotas terminarão suas planos em seu lugar.",
  ui_story_2002_6_91_dialog_content = "Já você e aquela gata são apenas uns fracassados.",
  ui_story_2002_6_92_dialog_content = "...",
  ui_story_2002_6_93_dialog_content = "Ah! Que bom voltar pra Illumina, mesmo que eu não possa ficar por muito tempo. Como será que <color=#FFB400>minha velha amiga</color> está agora?",
  ui_story_2002_6_94_dialog_content = "Será que está comandando alguns soldados em um cargo importante? Ou talvez tenha se enfiado em sua casa, satisfeita com o status quo...",
  ui_story_2002_6_95_dialog_content = "R-Reinhardt... simplesmente não é páreo pra você, mestre... Cof!",
  ui_story_2002_6_96_dialog_content = "Eu não preciso que você me diga isso. Meu ódio ferve silenciosamente, mas fará um barulho ensurdecedor quando meu plano for concretizado. Ela ainda vai ouvi-lo de um jeito ou de outro.",
  ui_story_2002_6_97_dialog_content = "Quanto a você... Feche os olhos. Vou te libertar do seu sofrimento. O sol acabou...",
  ui_story_2002_6_98_dialog_content = "<color=#e8d9bb>O olhar de Bowlinger brilhou uma última vez ao erguer sua cabeça aliviado, e ele então proferiu suas últimas palavras de devoção:</color>",
  ui_story_2002_6_99_dialog_content = "Eclipse existirá por toda a eternidade...",
  ui_story_2003_1_1_dialog_content = "Eu sabia que pertencia àquele magnífico palácio branco desde a primeira que o vi. Aquele era o meu <color=#FFB400>lar</color>...",
  ui_story_2003_1_2_dialog_content = "Não esta <color=#FFB400>Umbraton</color> suja e arruinada. Farei qualquer coisa pra...",
  ui_story_2003_1_3_dialog_content = "Miau... miau...",
  ui_story_2003_1_4_dialog_content = "Ah! Ai!",
  ui_story_2003_1_5_dialog_content = "Cuidado, Connolly!",
  ui_story_2003_1_6_dialog_content = "Caí sem querer de novo... Que desajeitada!",
  ui_story_2003_1_7_dialog_content = "<color=#e8d9bb>Era uma tarde de verão. Connolly e seu amigo clarinete, Anton, estavam limpando o porão do Café Holiday.</color>",
  ui_story_2003_1_8_dialog_content = "<color=#e8d9bb>Essa pequena sala empoeirada escondia o passado de Connolly.</color>",
  ui_story_2003_1_9_dialog_content = "São todas as partituras que trouxemos quando nos mudamos pra cá. Vejamos...",
  ui_story_2003_1_10_dialog_content = "Eu me lembro dessa! “Dança em Mi maior”, do Clarkson... Essa é “Hino do Vento”... e essa é “Polca de Litman”.",
  ui_story_2003_1_11_dialog_content = "Ahh, essa não é “Variação na Noite Branca”? Os nobres adoram coisas assim, tipo canções de coro com muitos acordes.",
  ui_story_2003_1_12_dialog_content = "Isso se chama solenidade.",
  ui_story_2003_1_13_dialog_content = "Por que estão brigando? Cuidado, está empoeirado, não é limpo há muito tempo.",
  ui_story_2003_1_14_dialog_content = "Ah, e essa é...",
  ui_story_2003_1_15_dialog_content = "<color=#e8d9bb>Anton entregou uma partitura simples, de capa amarela, apenas com a palavra \"Casa\" escrita no canto inferior direito.</color>",
  ui_story_2003_1_X15_dialog_content = "\"O único lugar onde podemos esconder todas as nossas falhas e fraquezas, um lugar de amor.\"",
  ui_story_2003_1_X16_dialog_content = "<color=#FFB400>“Casa”</color>, um palácio de amor, alegria e sorrisos... Que lindo!",
  ui_story_2003_1_16_dialog_content = "Connolly, por que não deixa a mãe te ensinar a tocar?",
  ui_story_2003_1_17_dialog_content = "Ah, isso... Achei que tivesse perdido há tempos. Foi a primeira canção que minha mãe me ensinou a tocar.",
  ui_story_2003_1_18_dialog_content = "*Cantarola suavemente*",
  ui_story_2003_1_19_dialog_content = "Você acertou alguma nota?",
  ui_story_2003_1_20_dialog_content = "O que importa aqui é a emoção! Minha emoção sincera e intensa!",
  ui_story_2003_1_21_dialog_content = "Mas nunca ouvi você tocar essa música. Você esqueceu como toca? Precisa olhar a partitura?",
  ui_story_2003_1_22_dialog_content = "Não, não preciso, eu só...",
  ui_story_2003_1_23_dialog_content = "Acho que ainda não tô pronta pra tocá-la. Afinal, ela se chama <color=#FFB400>“Casa”</color>...",
  ui_story_2003_1_24_dialog_content = "<color=#FFB400>Casa</color>?",
  ui_story_2003_1_25_dialog_content = "Será que não tá sentindo falta daquela casa branca grande?",
  ui_story_2003_1_26_dialog_content = "A antiga casa?",
  ui_story_2003_1_27_dialog_content = "Prefiro o Café Holiday. Eles têm comidas e bebidas muito boas... E muita gente estranha também.",
  ui_story_2003_1_28_dialog_content = "Desculpe interromper. Connolly, ouvi um pedido de ajuda.",
  ui_story_2003_1_29_dialog_content = "Um pedido de ajuda?",
  ui_story_2003_1_30_dialog_content = "Sim, vai e volta, e é muito fraco, como uma chama se apagando...",
  ui_story_2003_1_31_dialog_content = "Eu não posso ignorar isso! Eu não devo... ter medo! Vamos, Anton!",
  ui_story_2003_1_32_dialog_content = "Não é melhor pedir pra Dayna ou Robyn primeiro? E se encontrarmos uma gangue de Eclipsitas? Buá, seria assustador!",
  ui_story_2003_1_33_dialog_content = "Não vamos incomodá-las. Elas têm seus próprios afazeres...",
  ui_story_2003_1_34_dialog_content = "Acho que conseguimos fazer isso sozinhos.",
  ui_story_2003_1_35_dialog_content = "Ahhh!",
  ui_story_2003_1_36_dialog_content = "*Tocando o clarinete*",
  ui_story_2003_1_37_dialog_content = "Connolly! Você tá cada vez melhor nisso!",
  ui_story_2003_1_38_dialog_content = "É assim que é a vida em Umbraton, afinal...",
  ui_story_2003_1_39_dialog_content = "Não há barreira no céu e os Eclipsitas podem estar à espreita em qualquer lugar.",
  ui_story_2003_1_40_dialog_content = "Eu me sentia muito fraca antes... Mas parece que tô ficando mais forte agora.",
  ui_story_2003_1_41_dialog_content = "Ahh! Um Opressor!",
  ui_story_2003_1_42_dialog_content = "<size=45>Iiiihh!</size>",
  ui_story_2003_1_43_dialog_content = "A-aonde ele tá?!",
  ui_story_2003_1_44_dialog_content = "Ei, eu só tava brincando!",
  ui_story_2003_1_45_dialog_content = "Ai! Cuidado pra não atingir meus tentáculos!",
  ui_story_2003_1_46_dialog_content = "Pare de provocar, Connolly. Nós somos \"irmãos\", mas às vezes, você é muito chata.",
  ui_story_2003_1_47_dialog_content = "Então... está aqui? Está tão escuro... Eu não esperava ver becos tão escuros em Umbraton.",
  ui_story_2003_1_48_dialog_content = "Sim, posso ouvir claramente. O grito de socorro foi tão nítido agora...",
  ui_story_2003_1_49_dialog_content = "Mas isso parece um monte de caixas velhas...",
  ui_story_2003_1_50_dialog_content = "A-atchim! Tanta poeira... Tem alguém aí embaixo mesmo?",
  ui_story_2003_1_51_dialog_content = "Enfim, vamos tirar essas caixas do caminho e descobrir o que tem lá embaixo.",
  ui_story_2003_1_52_dialog_content = "Miau...",
  ui_story_2003_1_53_dialog_content = "Shhh... Você ouviu isso? Tem algo aí.",
  ui_story_2003_1_54_dialog_content = "O que tem debaixo das caixas?",
  ui_story_2003_1_55_dialog_content = "Senhor, você está bem? Não se preocupe! Vamos tirá-lo em um segundo... Ei...",
  ui_story_2003_1_56_dialog_content = "Miau... miau...",
  ui_story_2003_1_57_dialog_content = "Entendo...",
  ui_story_2003_1_58_dialog_content = "Um <color=#FFB400>gato</color>?",
  ui_story_2003_2_1_dialog_content = "A Guilda Cloudrover pode não se envolver com caridade, mas essas práticas desonestas podem ferir nossa reputação.",
  ui_story_2003_2_2_dialog_content = "Que rato esperto. Dayna, Robyn, agarrem e arranquem a cauda.",
  ui_story_2003_2_3_dialog_content = "Droga, Robyn! Cerque ele!",
  ui_story_2003_2_4_dialog_content = "Esse rato ousa correr livremente por nosso território... Temos que pegá-lo hoje.",
  ui_story_2003_2_5_dialog_content = "*Acena*",
  ui_story_2003_2_6_dialog_content = "Não acredito no que eu tô vendo! Ele tá deslizando? Ele corre muito!",
  ui_story_2003_2_7_dialog_content = "Quando eu o pegar, vou fazê-lo se ajoelhar e pedir por misericórdia...",
  ui_story_2003_2_8_dialog_content = "Ou talvez seja melhor dar uma boa surra!",
  ui_story_2003_2_9_dialog_content = "*Arf... arf...* Ugh...que chatice!",
  ui_story_2003_2_10_dialog_content = "Robyn, à sua esquerda!",
  ui_story_2003_2_11_dialog_content = "Espere, não tem saída! Como...",
  ui_story_2003_2_12_dialog_content = "Ele desapareceu.",
  ui_story_2003_2_13_dialog_content = "Aaarrgh!",
  ui_story_2003_2_14_dialog_content = "Essa simpática ralé foi reunida e presa...",
  ui_story_2003_2_15_dialog_content = "Ei!",
  ui_story_2003_2_16_dialog_content = "*Cortando com a espada*",
  ui_story_2003_2_17_dialog_content = "Droga!  Perseguimos por tanto tempo e não deu em nada... Já consigo ouvir a chefe zombando de nós.",
  ui_story_2003_2_18_dialog_content = "E tenho certeza que não vamos receber nosso salário agora. Meu crânio tá sacudindo agora...",
  ui_story_2003_2_19_dialog_content = "Uma coisa é certa... aquele cara não é um homem de negócios qualquer.",
  ui_story_2003_2_20_dialog_content = "Café...",
  ui_story_2003_2_21_dialog_content = "Temos que continuar, mesmo que o trabalho não tenha sido feito.",
  ui_story_2003_2_22_dialog_content = "Vamos tomar um café na Connolly e descansar um pouco.",
  ui_story_2003_2_23_dialog_content = "Aqui está, café expresso e leite fresco pelo seu trabalho duro, meninas.",
  ui_story_2003_2_24_dialog_content = "Humm! Seu café é de outro mundo, Connolly. Tô num dilema agora, quero que você volte a trabalhar na guilda, mas ao mesmo tempo não consigo abrir mão desse café...",
  ui_story_2003_2_25_dialog_content = "Então aquela pessoa era...",
  ui_story_2003_2_26_dialog_content = "Ele era um comerciante oficial da Guilda Cloudrover. Estávamos rastreando há um bom tempo. Já ouviu falar do <color=#FFB400>Extrato de Ouro Branco</color>?",
  ui_story_2003_2_27_dialog_content = "<color=#FFB400>Extrato de Ouro Branco</color>?",
  ui_story_2003_2_28_dialog_content = "Um tipo de líquido branco com cubos dourados transparentes dentro, parece uma geleia com leite.",
  ui_story_2003_2_29_dialog_content = "Dizem que permite <color=#FFB400>a purificação da linhagem, liberando a entrada das pessoas em Lumópolis</color>.",
  ui_story_2003_2_30_dialog_content = "É difícil de acreditar...",
  ui_story_2003_2_31_dialog_content = "Né? Mas para aqueles que passaram a vida toda em Umbraton, viajar pra Lumópolis é mais do que simplesmente entrar em uma aeronave no Centro de Transporte.",
  ui_story_2003_2_32_dialog_content = "Pra eles, são dois mundos completamente diferentes.",
  ui_story_2003_2_33_dialog_content = "Hum...",
  ui_story_2003_2_34_dialog_content = "Ele pode oferecer uma sensação de prazer, como se fosse um poder inesgotável. Mas ao mesmo tempo, aqueles que tomarem o extrato atrairão os Eclipsitas,",
  ui_story_2003_2_35_dialog_content = "<size=45>tornando-se suas presas</size>.",
  ui_story_2003_2_36_dialog_content = "Porém, ainda existe muita gente que não acredita nos efeitos colaterais do extrato de ouro branco, perseguindo-o fanaticamente.",
  ui_story_2003_2_37_dialog_content = "O cara que vende isso não tem absolutamente nenhuma consideração pela guilda.",
  ui_story_2003_2_38_dialog_content = "Haverá novas vítimas.",
  ui_story_2003_2_39_dialog_content = "Sim...",
  ui_story_2003_2_40_dialog_content = "Ah, acabou o café.",
  ui_story_2003_2_41_dialog_content = "Sem problemas, eu trago mais pra você.",
  ui_story_2003_2_42_dialog_content = "Obrigada... é muito gentil da sua parte, Connolly.",
  ui_story_2003_2_43_dialog_content = "Ah, eu tava querendo perguntar desde que entrei. O que é aquilo na mesa?",
  ui_story_2003_2_44_dialog_content = "É... er... é um gato robótico.",
  ui_story_2003_2_45_dialog_content = "<color=#e8d9bb>Connolly contou o que aconteceu para Dayna e Robyn.</color>",
  ui_story_2003_2_46_dialog_content = "Ah... é um robô. É bem curioso. Ele se move?",
  ui_story_2003_2_47_dialog_content = "Não, espere um pouco... Você foi destruir os Eclipsitas? Por que não nos contou? E se você tivesse se metido em uma situação perigosa?",
  ui_story_2003_2_48_dialog_content = "Como sempre, indo sozinha. Todos aqueles Eclipsitas... Você...",
  ui_story_2003_2_49_dialog_content = "Dayna...",
  ui_story_2003_2_50_dialog_content = "Tá bem, tá bem, não falo mais nada... Mas conte pra gente da próxima vez! Afinal, nós somos sua <color=#FFB400>família</color>!",
  ui_story_2003_2_51_dialog_content = "Tá-tá bem, vocês decidem.",
  ui_story_2003_2_52_dialog_content = "Agora nos conte mais sobre o gato. O que ele pode fazer?",
  ui_story_2003_2_53_dialog_content = "Quando eu o encontrei, ele ainda fazia alguns barulhos, mas agora só fica parado e em silêncio. Talvez esteja... quebrado?",
  ui_story_2003_2_54_dialog_content = "Deixe comigo. Sou boa nisso.",
  ui_story_2003_2_55_dialog_content = "Diga que não vai usar violência.",
  ui_story_2003_2_56_dialog_content = "Zzzzsshhh... Miau! Miau!",
  ui_story_2003_2_57_dialog_content = "Uau, você consertou mesmo!",
  ui_story_2003_2_58_dialog_content = "Eu não disse?",
  ui_story_2003_2_59_dialog_content = "Ele também se lambe e se esfrega nas nossas pernas. Ah, hora de fazer carinho...",
  ui_story_2003_2_60_dialog_content = "Achei vocês! Dayna e Robyn... vocês vieram escondidas pro Café Holiday durante o horário de trabalho, de novo?\nTerei que descontar dos seus salários!",
  ui_story_2003_2_61_dialog_content = "Droga, o dever chama. Até a próxima.",
  ui_story_2003_2_62_dialog_content = "Tchau, Connolly.",
  ui_story_2003_2_63_dialog_content = "Ah, e não coloque açúcar no expresso da próxima vez...",
  ui_story_2003_2_64_dialog_content = "Parece que estamos sozinhos novamente.",
  ui_story_2003_2_65_dialog_content = "É, mas temos o gato.",
  ui_story_2003_2_66_dialog_content = "O gato... Ei, onde ele está?",
  ui_story_2003_2_67_dialog_content = "<color=#e8d9bb>A porta do Café balançou suavemente. Aquela criaturinha silenciosa tinha saído sem ser notada.</color>",
  ui_story_2003_3_1_dialog_content = "Pra onde ele foi?",
  ui_story_2003_3_2_dialog_content = "Relaxa, Connolly. Já consigo sentir o cheiro dele.",
  ui_story_2003_3_3_dialog_content = "Este é o... Centro de Transporte? É bem ali!",
  ui_story_2003_3_4_dialog_content = "Cidadãos de Umbraton? E da área mais suja? Vocês nem tem passagem.",
  ui_story_2003_3_5_dialog_content = "Não sou um dos nobres, mas trabalhei pra eles. Tenho todas as qualificações necessárias, \nentão por gentileza deixe-me entrar em Lumópolis, senhor.",
  ui_story_2003_3_6_dialog_content = "Chega. Vá embora. Não obstrua as atividades oficiais.",
  ui_story_2003_3_7_dialog_content = "Sem pressa. Você aí... nos conte mais sobre suas qualificações.",
  ui_story_2003_3_8_dialog_content = "Eu me chamo Krane e sou um mecânico especializado em... estudar a tecnologia Lúmina das antigas civilizações.",
  ui_story_2003_3_9_dialog_content = "Você deve ter ouvido falar de mim! Já estive em Lumópolis e fiz alguns produtos mecânicos para a família Troy! Dê uma olhada neste relógio.",
  ui_story_2003_3_10_dialog_content = "Ah, ele é bem bonito.",
  ui_story_2003_3_11_dialog_content = "Então...",
  ui_story_2003_3_12_dialog_content = "Mas Lumópolis não precisa desses aparelhos inúteis.",
  ui_story_2003_3_13_dialog_content = "Krane, é claro, já ouvimos esse nome... O talentoso mecânico que afirmava ter dominado a tecnologia das civilizações antigas... não passa de um amador.",
  ui_story_2003_3_14_dialog_content = "Você criou um gato que canta e o trouxe para os nobres, não foi? No entanto, acabou que o gato era mudo. Depois disso, você e seu gato foram banidos de Lumópolis.",
  ui_story_2003_3_15_dialog_content = "Será que é esse gato?",
  ui_story_2003_3_16_dialog_content = "<color=#e8d9bb>Um gato preto apareceu de repente aos pés do mecânico, sentando obedientemente e olhando-o com seus grandes olhos.</color>",
  ui_story_2003_3_17_dialog_content = "Mas, senhor... e-eu também posso demonstrar algumas outras habilidades. Eu só... não consigo pensar em nada agora... Droga...",
  ui_story_2003_3_18_dialog_content = "Enfim, farei o meu melhor para conseguir um emprego em Lumópolis.",
  ui_story_2003_3_19_dialog_content = "Saia daqui. Você já desperdiçou muito o nosso tempo.",
  ui_story_2003_3_20_dialog_content = "Miau...",
  ui_story_2003_3_21_dialog_content = "Qual é o problema desse gato?!",
  ui_story_2003_3_22_dialog_content = "Pegue ele! Ele atacou os guardas ferozmente. Temos que levá-lo para a Corte de Justiça!",
  ui_story_2003_3_23_dialog_content = "Senhor... Não... Por favor...",
  ui_story_2003_3_24_dialog_content = "Anton!",
  ui_story_2003_3_X24_dialog_content = "Opa! Guardas Lumo procurando encrenca!",
  ui_story_2003_3_25_dialog_content = "Mas tudo bem. Connolly, vamos botá-los pra dormir agora.",
  ui_story_2003_3_26_dialog_content = "Finalmente... está seguro! Não se preocupe, e-eu não os machuquei. Só desejei bons sonhos.",
  ui_story_2003_3_27_dialog_content = "...",
  ui_story_2003_3_28_dialog_content = "Tudo bem?",
  ui_story_2003_3_29_dialog_content = "Quase tive a chance de voltar pra Lumópolis, mas você apareceu e estragou tudo!",
  ui_story_2003_3_30_dialog_content = "Miau... miau...",
  ui_story_2003_3_31_dialog_content = "Você de novo? Achei que estivesse quebrado...",
  ui_story_2003_3_32_dialog_content = "Por que está me seguindo? Eu não estaria em Umbraton se não fosse por você, seu pedaço de...\nEu já era um convidado dos nobres...",
  ui_story_2003_3_33_dialog_content = "<size=45>Saia da minha frente... Agora!</size>",
  ui_story_2003_3_34_dialog_content = "Ah, você...",
  ui_story_2003_3_35_dialog_content = "Ele fugiu...",
  ui_story_2003_3_36_dialog_content = "Qual o problema daquele cara? Nós o ajudamos, mas ele não só não gostou, como até deixou o coitadinho aqui.",
  ui_story_2003_3_37_dialog_content = "Gatinho... Você não vai atrás dele?",
  ui_story_2003_3_38_dialog_content = "Papai... mamãe? Pra onde vocês vão?",
  ui_story_2003_3_39_dialog_content = "Connolly, pode nos aguardar aqui?",
  ui_story_2003_3_X39_dialog_content = "Em breve retornaremos a Lumópolis, nossa verdadeira casa.",
  ui_story_2003_3_X40_dialog_content = "Pode ser que você se sinta sozinha...",
  ui_story_2003_3_X41_dialog_content = "Aqui, este é o meu clarinete... Deve servir um pouco de conforto.",
  ui_story_2003_3_X42_dialog_content = "É como naquela época...",
  ui_story_2003_3_40_dialog_content = "Parou de se mover, Connolly...",
  ui_story_2003_3_41_dialog_content = "acabou a Lúmina...",
  ui_story_2003_3_42_dialog_content = "Hoje não é o meu dia... Por que... Por que...?",
  ui_story_2003_3_43_dialog_content = "Não há nada além de degradação e escuridão. Vivendo com dificuldade e comida estragada numa pobreza sem-fim.",
  ui_story_2003_3_44_dialog_content = "Eu não aguento mais. Eu odeio este lugar. Não tenho mais nenhuma satisfação... Eu só quero ir pra <color=#FFB400>casa</color>!!!",
  ui_story_2003_3_45_dialog_content = "Você quer ir pra Lumópolis?",
  ui_story_2003_3_46_dialog_content = "Quem... quem era?!",
  ui_story_2003_3_47_dialog_content = "Não entende?",
  ui_story_2003_3_48_dialog_content = "Esses seus truques podem fazê-la entrar em Lumópolis, mas nunca a farão cruzar a barreira das linhagens. Para ficar lá, você precisa de sangue nobre, coisa que você não tem.",
  ui_story_2003_3_49_dialog_content = "Mas o que posso fazer? Eu sou inferior por natureza... Vou ter que ficar neste lugar imundo pra sempre?",
  ui_story_2003_3_50_dialog_content = "Por que não tenta algo diferente?",
  ui_story_2003_3_51_dialog_content = "Beba. Isso purificará seu sangue de toda a sujeira. Assim, você poderá se juntar à sociedade de Lumópolis.",
  ui_story_2003_3_52_dialog_content = "Experimente.",
  ui_story_2003_4_1_dialog_content = "Já estava quebrado antes... Aí tomou um soco da Dayna, um chute do guarda, e depois foi deixado de lado pelo seu dono.",
  ui_story_2003_4_2_dialog_content = "É um milagre que não tenha se despedaçado!",
  ui_story_2003_4_3_dialog_content = "Sim... De fato.",
  ui_story_2003_4_4_dialog_content = "Se ele tivesse feito um bom uso desse dom, com certeza poderia ganhar muito dinheiro. É uma pena que...",
  ui_story_2003_4_5_dialog_content = "Existem muitas pessoas com sonhos fora da realidade que querem chegar aos palácios brancos de Lumópolis.",
  ui_story_2003_4_6_dialog_content = "Os coitados que tentavam entrar escondido em Lumópolis pelo Centro de Transporte foram empurrados no meio do caminho e ficaram inválidos.",
  ui_story_2003_4_7_dialog_content = "Quem chega muito perto do sol, morre queimado... Acredito que você já tenha morado em Lumópolis, né?",
  ui_story_2003_4_8_dialog_content = "Eu era muito jovem naquela época... e não gostava muito de lá...",
  ui_story_2003_4_9_dialog_content = "Connolly...",
  ui_story_2003_4_10_dialog_content = "*Balança a cabeça*",
  ui_story_2003_4_11_dialog_content = "Última parte e... Pronto! É tudo o que posso fazer.",
  ui_story_2003_4_12_dialog_content = "Não, está ótimo. Eu agradeço!",
  ui_story_2003_4_13_dialog_content = "<color=#e8d9bb>O gatinho mecânico recarregado limpou-se alegremente sobre a mesa e encostou a cabeça na mão de Connolly.</color>",
  ui_story_2003_4_14_dialog_content = "Sobre o dinheiro...",
  ui_story_2003_4_15_dialog_content = "Shhh... Mesmo que eu adore dinheiro e tesouros tanto quanto um dragão, eu não aceito qualquer dinheiro... Que tal mais um café?",
  ui_story_2003_4_16_dialog_content = "Hã?",
  ui_story_2003_4_17_dialog_content = "O que há de tão estranho nisso? Minha querida, você é nossa família.",
  ui_story_2003_4_18_dialog_content = "Você será sempre bem-vinda entre nós...",
  ui_story_2003_4_19_dialog_content = "Sheol, Dayna, Robyn e...",
  ui_story_2003_4_20_dialog_content = "Connolly?",
  ui_story_2003_4_21_dialog_content = "Acorde e limpe o café. Café...",
  ui_story_2003_4_22_dialog_content = "É da Dayna? Ela deixou aqui? Aqui diz que...",
  ui_story_2003_4_23_dialog_content = "Outra vítima comprou o extrato... Krane... o mecânico!!",
  ui_story_2003_4_24_dialog_content = "Ele queria tanto chegar em Lumópolis... Agora ele vai tomar o extrato! O que devemos fazer? Temos que ajudá-lo!",
  ui_story_2003_4_25_dialog_content = "Não, espere um momento....",
  ui_story_2003_4_26_dialog_content = "Da próxima vez, fale com a gente! Afinal, somos sua <color=#FFB400>família</color>!",
  ui_story_2003_4_27_dialog_content = "Você quer deixar uma mensagem pra Dayna?",
  ui_story_2003_4_28_dialog_content = "Sim. Vou escrever no quadro! \"Para Dayna e Robyn, há uma nova vítima. Espero por vocês lá.\"",
  ui_story_2003_4_29_dialog_content = "Miau...",
  ui_story_2003_4_30_dialog_content = "Você conhece o lugar, não é?",
  ui_story_2003_4_31_dialog_content = "Miau... miau...",
  ui_story_2003_4_32_dialog_content = "Vamos juntos!",
  ui_story_2003_4_X1_dialog_content = "Beba... beba...",
  ui_story_2003_4_X2_dialog_content = "Eu quero... tanto isso...",
  ui_story_2003_4_X3_dialog_content = "Beba e você ficará mais forte, mais saboroso também ...",
  ui_story_2003_4_X4_dialog_content = "Entendo sua hesitação, então não tenha pressa... Lembre-se, você encontrará o caminho certo em algum momento.",
  ui_story_2003_4_33_dialog_content = "Tá cheio de Opressores... Ah, eles são tão difíceis de enxergar no escuro... Não são muito perigosos, mas são muito chatos.",
  ui_story_2003_4_34_dialog_content = "Está completamente escuro aqui também. Parece com a casa dele. Chegamos a tempo?",
  ui_story_2003_4_35_dialog_content = "T-tem alguém aqui?",
  ui_story_2003_4_36_dialog_content = "Falei baixo? TEM ALGUÉM AQUI?",
  ui_story_2003_4_37_dialog_content = "Miau...",
  ui_story_2003_4_38_dialog_content = "Nossa, ele até abre a porta! Há, ele claramente é inteligente o suficiente pra ser um membro da nossa banda! Vamos chamá-lo de Anton Ré menor...",
  ui_story_2003_4_39_dialog_content = "Silêncio, ainda não sabemos o que tá acontecendo.",
  ui_story_2003_4_40_dialog_content = "A porta não tá trancada...",
  ui_story_2003_4_41_dialog_content = "Ah! Tá tudo bem, senhor mecânico?",
  ui_story_2003_4_42_dialog_content = "Miau... miau...",
  ui_story_2003_4_43_dialog_content = "Você de novo? A garota barulhenta... e essa porcaria. Por que estão aqui?",
  ui_story_2003_4_44_dialog_content = "Mas não importa...",
  ui_story_2003_4_X44_dialog_content = "Já sei como chegar em Lumópolis.",
  ui_story_2003_5_1_dialog_content = "<color=#e8d9bb>O frasco vazio estava caído no chão, levemente rachado pela queda e com apenas um pouco de fluido de platina dentro.</color>",
  ui_story_2003_5_2_dialog_content = "Já posso ver. Estou sentado em uma aeronave que o vento leva ao ar, e depois, pisando nas nuvens, chego ao portão frontal de Lumópolis.",
  ui_story_2003_5_3_dialog_content = "Sou recebido por anjos uniformizados que tocam suas trombetas pra me dar as boas-vindas, e então abrem os portões...",
  ui_story_2003_5_4_dialog_content = "Tem também um nobre, que me olha com um sorriso no rosto e me pega pelo braço pra me acompanhar até um palácio.",
  ui_story_2003_5_5_dialog_content = "Um cheiro de comida no ar...",
  ui_story_2003_5_6_dialog_content = "Ahhh, isso... Isso é...",
  ui_story_2003_5_7_dialog_content = "Ele já bebeu...",
  ui_story_2003_5_8_dialog_content = "Sr. Krane... Senhor... Tá me ouvindo?!",
  ui_story_2003_5_9_dialog_content = "É essa... a vida que eu quero?",
  ui_story_2003_5_10_dialog_content = "Connolly, cuidado!",
  ui_story_2003_5_11_dialog_content = "Argh...",
  ui_story_2003_5_12_dialog_content = "Como Dayna falou, ele já se tornou a isca dos Eclipsitas.",
  ui_story_2003_5_13_dialog_content = "Eles estão todos escondidos nesta sala... Arghhh! Quantos são?!",
  ui_story_2003_5_14_dialog_content = "Eles estão à espreita no escuro, mas agora não é hora pra esconde-esconde!",
  ui_story_2003_5_15_dialog_content = "Mantenham a calma e não entrem em pânico...",
  ui_story_2003_5_16_dialog_content = "Anton! Vamos limpar toda essa bagunça juntos!",
  ui_story_2003_5_17_dialog_content = "Mas por que estou me sentindo tão... vazio?",
  ui_story_2003_5_18_dialog_content = "Aquela pessoa disse claramente: beba e você renascerá, seu sangue sujo será purificado e um sangue nobre correrá em suas veias.",
  ui_story_2003_5_19_dialog_content = "Os portões de Lumópolis se abrirão pra você, levando não só ao pátio, mas também aos jardins.",
  ui_story_2003_5_20_dialog_content = "Você tocará a luz do ponto mais alto de Lumópolis e sua alma encontrará o seu lar.",
  ui_story_2003_5_21_dialog_content = "Mas por que estou me sentindo tão... vazio?",
  ui_story_2003_5_22_dialog_content = "Meu gatinho, aquele que levei a minha vida toda criando e desenvolvendo com o meu conhecimento. Responda! Por que você não canta?",
  ui_story_2003_5_23_dialog_content = "Miau...",
  ui_story_2003_5_24_dialog_content = "É o último! Acabou!",
  ui_story_2003_5_25_dialog_content = "Sr. Krane... Você... Como?!",
  ui_story_2003_5_26_dialog_content = "<color=#e8d9bb>Os Opressores à espreita na escuridão surgiram repentinamente do caos.</color>",
  ui_story_2003_5_27_dialog_content = "<color=#e8d9bb>Eles roeram o braço do mecânico, mas ele nem percebeu o que estava acontecendo.</color>",
  ui_story_2003_5_28_dialog_content = "Quanto mais Opressores apareciam, mais ele se tornava um chamariz, atraindo Eclipsitas sem parar. E seu corpo parecia estar se transformando...",
  ui_story_2003_5_29_dialog_content = "Rápido! Vamos acabar com esses malditos Opressores! Ugh, é tão sujo! Eu não aguento mais!",
  ui_story_2003_5_30_dialog_content = "Sem dor, sem frio, sem tristeza... Esta é exatamente a vida que eu desejo... Mas...",
  ui_story_2003_5_31_dialog_content = "Por que...",
  ui_story_2003_5_32_dialog_content = "Sr. Krane! Sr. Krane... Se não acabarmos com isso... Você irá...",
  ui_story_2003_5_X1_dialog_content = "<color=#FFB400>\"Morra.\"</color>",
  ui_story_2003_5_33_dialog_content = "Se tiver que ser... tudo bem. Afinal, não alcancei a satisfação no fim. Finalmente, finalmente...",
  ui_story_2003_5_34_dialog_content = "<color=#e8d9bb>O mecânico ergueu levemente a cabeça, frágil como uma folha de papel, esperando ser coberto pelos Eclipsitas.</color>",
  ui_story_2003_5_35_dialog_content = "<color=#e8d9bb>O gato preto desgastado ficou em silêncio, só sentado ali, observando e absorvendo tudo.</color>",
  ui_story_2003_6_1_dialog_content = "Você sente falta de Lumópolis, Connolly?",
  ui_story_2003_6_2_dialog_content = "As paredes altas e cúpulas, os prédios brancos iluminados pelo pôr do sol, os soldados protegendo os muros... e nada de Eclipsitas.",
  ui_story_2003_6_3_dialog_content = "Lá também é a nossa casa.",
  ui_story_2003_6_4_dialog_content = "Mas o lar não é onde a família está? Tô muito feliz agora, morando com mamãe e papai!",
  ui_story_2003_6_5_dialog_content = "Connolly, você não entende. Esta casinha velha não é o nosso verdadeiro lar.",
  ui_story_2003_6_6_dialog_content = "É... eu não entendo. Não há diferença entre os dois.",
  ui_story_2003_6_7_dialog_content = "Mas você tá tão determinado a ir embora... O que acabou restando pra mim não foi a promessa de voltar pra Lumópolis, mas sim...\nseus obituários.",
  ui_story_2003_6_8_dialog_content = "Estou sozinha desde então, passando a maior parte da infância e adolescência dentro e fora da casa de parentes, sem um lugar seguro pra onde ir.",
  ui_story_2003_6_9_dialog_content = "A magnífica Lumópolis não é minha casa... Adoraria dizer isso... Gostaria que você pudesse me ouvir.",
  ui_story_2003_6_10_dialog_content = "(Choro não identificado)",
  ui_story_2003_6_11_dialog_content = "A transformação foi bem-sucedida?",
  ui_story_2003_6_12_dialog_content = "Caramba!!! O que é isso?! De onde vieram esses Eclipsitas? Este é o local de onde eles surgem?",
  ui_story_2003_6_13_dialog_content = "Mas a dupla Anton e Connolly é invencível! Juntos nós podemos...",
  ui_story_2003_6_14_dialog_content = "...",
  ui_story_2003_6_15_dialog_content = "Você vai voltar atrás sem falar nada?",
  ui_story_2003_6_16_dialog_content = "Infelizmente, todos os experimentos anteriores falharam. Mas você deve estar se sentindo um pouco diferente, né? Depois de beber o extrato concentrado.",
  ui_story_2003_6_17_dialog_content = "Transformação... Não os Aurorians de Lumópolis, mas a presa dos Eclipsitas...",
  ui_story_2003_6_Z17_dialog_content = "Pra ser exato, a ideia é se tornar uma comida mais deliciosa. Sua carne e sangue serão transformados no catalisador que os Eclipsitas desejam.",
  ui_story_2003_6_Z18_dialog_content = "É uma pena que não tenha ocorrido tudo perfeitamente, mas seria um desperdício deixar isso para aqueles insetos idiotas.",
  ui_story_2003_6_Z19_dialog_content = "Deixe-me experimentar com cuidado.",
  ui_story_2003_6_Z20_dialog_content = "Hum... Aaaaaaaaah!",
  ui_story_2003_6_18_dialog_content = "Sr. Krane!",
  ui_story_2003_6_19_dialog_content = "Eclipsitas de alto nível! Você... você que fez este maldito extrato?",
  ui_story_2003_6_20_dialog_content = "Não, não, não... Isso não é possível. Sou apenas um simples... distribuidor.",
  ui_story_2003_6_21_dialog_content = "Um artefato tão grandioso e sagrado só pode vir da gloriosa Lumópolis... Eu apenas o aprimorei um pouco.",
  ui_story_2003_6_X1_dialog_content = "A felicidade é tão fácil de se obter... Dê isso aos pobres rejeitados, leve-os à paz e à serenidade...",
  ui_story_2003_6_X2_dialog_content = "E então deixe que eles se tornem o que mais desejamos.",
  ui_story_2003_6_X3_dialog_content = "Lumópolis... Como...",
  ui_story_2003_6_X4_dialog_content = "Pena que a transformação ainda não foi concluída. Mas ele terá um ótimo sabor assim mesmo.",
  ui_story_2003_6_X5_dialog_content = "Poderia não interromper minha refeição, fofinha? Ou você também quer ser transformada?",
  ui_story_2003_6_X6_dialog_content = "Quero que pare com essas atrocidades agora.",
  ui_story_2003_6_X7_dialog_content = "Não poderei realizar o seu desejo.",
  ui_story_2003_6_X8_dialog_content = "Aahhhhhh!",
  ui_story_2003_6_X9_dialog_content = "Tanto poder É difícil controlar! Essa é uma energia completamente diferente dos outros Eclipsitas. O Fluxo Escuro é tão denso, como se quisesse afogar as pessoas nele.",
  ui_story_2003_6_X10_dialog_content = "Anton...",
  ui_story_2003_6_X11_dialog_content = "Aguente firme, Connolly!",
  ui_story_2003_6_X12_dialog_content = "Você agiu por conta própria novamente, Connolly.",
  ui_story_2003_6_X13_dialog_content = "Mas pelo menos dessa vez você fez algum progresso e nos deixou mensagens no quadro.",
  ui_story_2003_6_X14_dialog_content = "<color=#FFB400>“Família”</color>.",
  ui_story_2003_6_X15_dialog_content = "Dayna, Robyn! Vocês...",
  ui_story_2003_6_X16_dialog_content = "Você sempre terá um lugar seguro. É o mesmo quando vamos ao Café Holiday pra relaxar e nos divertir.",
  ui_story_2003_6_X17_dialog_content = "Sim!",
  ui_story_2003_6_X18_dialog_content = "Ei, Eclipsita.",
  ui_story_2003_6_X19_dialog_content = "Você anda vendendo produtos proibidos e atacando membros da Guilda... E quanto ao dinheiro perdido devido ao tempo que você está foragido, hein?\nVamos acertar nossas contas com você hoje, uma por uma.",
  ui_story_2003_6_22_dialog_content = "Acabou...",
  ui_story_2003_6_23_dialog_content = "É... Ufa.",
  ui_story_2003_6_24_dialog_content = "O gato...",
  ui_story_2003_6_25_dialog_content = "Pluto...",
  ui_story_2003_6_26_dialog_content = "Miau, miau...",
  ui_story_2003_6_27_dialog_content = "Dê um momento a eles.",
  ui_story_2003_6_28_dialog_content = "*Começa a cantarolar*",
  ui_story_2003_6_29_dialog_content = "É <color=#FFB400>“Casa”</color>.",
  ui_story_2003_6_30_dialog_content = "A música que sua mãe te ensinou?",
  ui_story_2003_6_31_dialog_content = "Sim, morávamos em Umbraton naquela época e éramos pobres. Apesar de já termos sido nobres, nossa vida se tornou pior do que a de muitos plebeus.",
  ui_story_2003_6_32_dialog_content = "Mas eu era muito feliz, porque mamãe e papai estavam lá... Mas aí...",
  ui_story_2003_6_33_dialog_content = "Como pode ser? Você sem dúvida sabe cantar...",
  ui_story_2003_6_34_dialog_content = "Será que você se recusa a cantar para aquelas pessoas porque... você só quer cantar essa música pra mim?",
  ui_story_2003_6_35_dialog_content = "Será? Eu sinto que... meu vazio foi preenchido...",
  ui_story_2003_6_36_dialog_content = "Mi!",
  ui_story_2003_6_37_dialog_content = "Saia daqui. Tá desabando.",
  ui_story_2003_6_38_dialog_content = "Eu também não tenho certeza... Mas ele disse que é de Lumópolis.",
  ui_story_2003_6_39_dialog_content = "É Lumópolis mesmo...",
  ui_story_2003_6_40_dialog_content = "Consegue ficar de pé? Vamos juntos...",
  ui_story_2003_6_41_dialog_content = "Não há mais tempo... Por favor, se puder, dê um lar a ele.",
  ui_story_2003_6_42_dialog_content = "Meu lar... Desmoronou...",
  ui_story_2003_6_X42_dialog_content = "Dayna, Robyn... Eu... Eu quero dizer uma coisa.",
  ui_story_2003_6_43_dialog_content = "Lembro de Lumópolis como um lugar de fontes, flores e sol criado pelo homem... lugar que pode ser chamado de paraíso.",
  ui_story_2003_6_44_dialog_content = "Mas percebi que não são essas coisas superficiais que fazem as pessoas felizes.",
  ui_story_2003_6_45_dialog_content = "Quando eu tava no fundo do poço, não foram os jardins nem os nobres que me salvaram... Foi o chefe, Sr. Istvan, e você.",
  ui_story_2003_6_46_dialog_content = "Obrigada... Vamos voltar para o café e tomar um cappuccino!",
  ui_story_2003_6_47_dialog_content = "<color=#e8d9bb>O pequeno café não dava dinheiro e estava sempre exposto a ameaças perigosas, mas se tornou o novo lar do gatinho.</color>",
  ui_story_2003_6_48_dialog_content = "Dayna, pare de martelar ele, vai estragar.",
  ui_story_2003_6_49_dialog_content = "Ei, tô tentando consertar!",
  ui_story_2003_6_50_dialog_content = "*Silenciosamente puxa uma arma*",
  ui_story_2003_6_51_dialog_content = "Miau...!!",
  ui_story_2003_6_52_dialog_content = "Ei, por que ele tá fugindo?",
  ui_story_2003_6_53_dialog_content = "Não sabia que objetos mecânicos tinham um desejo de sobrevivência tão forte e eram tão rápidos em uma situação de vida ou morte.",
  ui_story_2003_6_54_dialog_content = "Eu ia te mostrar minhas novas habilidades de conserto. Hã? Cadê meu café?\nEu lembro que nem toquei nele...",
  ui_story_2003_6_55_dialog_content = "*Bebendo o café fazendo barulho*",
  ui_story_2003_6_56_dialog_content = "Tudo bem. Vou pegar outro pra você.",
  ui_story_2003_6_57_dialog_content = "Humm... Estranho. Fantasmas assombram em plena luz do dia?",
  ui_story_2003_6_58_dialog_content = "Prefiro não contar pra Dayna que Anton bebeu o café.",
  ui_story_2003_6_59_dialog_content = "<color=#e8d9bb>Quanto à Connolly, seria o mesmo também.</color>",
  ui_story_2004_1_1_dialog_content = "Eu vejo o gelo e a neve, que nunca derretem, não importa a estação.",
  ui_story_2004_1_2_dialog_content = "Como uma barreira que mantém o inimigo do lado de fora, mas também impede meu caminho.",
  ui_story_2004_1_3_dialog_content = "Presa na minha própria armadilha, minha responsabilidade forja as próprias correntes que me amarram.",
  ui_story_2004_1_4_dialog_content = "Todo esse tempo é o suficiente pra congelar um coração ardente.",
  ui_story_2004_1_5_dialog_content = "<color=#FFB400>Eu sou a Rainha de Northland, mas também sou uma prisioneira de Northland.</color>",
  ui_story_2004_1_6_dialog_content = "Isso é ruim! Muito ruim!",
  ui_story_2004_1_7_dialog_content = "Esquerda!",
  ui_story_2004_1_8_dialog_content = "Direita!",
  ui_story_2004_1_9_dialog_content = "Os Eclipsitas estão muito fortes dessa vez.",
  ui_story_2004_1_10_dialog_content = "Olha o meu boneco de neve gigante! Ele não vai deixar nenhum deles passar!",
  ui_story_2004_1_11_dialog_content = "Noah, olhe para o do meio! Parece estar chamando reforços.",
  ui_story_2004_1_12_dialog_content = "Woogagagagaga!!!",
  ui_story_2004_1_13_dialog_content = "Parece que ele invocou...",
  ui_story_2004_1_14_dialog_content = "É tão grande...",
  ui_story_2004_1_15_dialog_content = "É tão grande...",
  ui_story_2004_1_16_dialog_content = "Sua altura equivale a seis Louises",
  ui_story_2004_1_17_dialog_content = "Todos os Eclipsitas podem ser altos assim? Isso é fantástico...",
  ui_story_2004_1_18_dialog_content = "Droga, eu achava que nada poderia superar meu boneco de neve em tamanho. Eu nunca vou esquecer isso.",
  ui_story_2004_1_19_dialog_content = "Ah! É um ataque!",
  ui_story_2004_1_20_dialog_content = "Não é hora de descansar.",
  ui_story_2004_1_21_dialog_content = "É um mar sem fim de Eclipsitas!",
  ui_story_2004_1_22_dialog_content = "Socorro! Precisamos de reforços! Precisamos de reforços!",
  ui_story_2004_1_23_dialog_content = "Solicitando reforços!",
  ui_story_2004_1_24_dialog_content = "Shh... Louise, Noah, fiquem quietas.",
  ui_story_2004_1_25_dialog_content = "Vocês vão acordar minha irmã.",
  ui_story_2004_1_26_dialog_content = "Nikinis!",
  ui_story_2004_1_27_dialog_content = "E Sua Majestade!",
  ui_story_2004_1_28_dialog_content = "Assim como a maré, a onda de Eclipsitas vai diminuir.",
  ui_story_2004_1_29_dialog_content = "Para trás, eles estão condenados a serem soterrados por gelo e neve, sem deixar nenhum vestígio.",
  ui_story_2004_1_30_dialog_content = "Estão todos... congelados.",
  ui_story_2004_1_31_dialog_content = "Como pingentes de gelo brotando do chão!",
  ui_story_2004_1_32_dialog_content = "Toda vez que vejo Sua Majestade demonstrar sua verdadeira força, meu coração se enche de admiração.",
  ui_story_2004_1_33_dialog_content = "Os pingentes de gelo se estilhaçaram e desapareceram sem deixar vestígio...",
  ui_story_2004_1_34_dialog_content = "Assim como a água que evapora no ar, não resta mais nada!",
  ui_story_2004_1_35_dialog_content = "Esse é o milagre de Northland.",
  ui_story_2004_1_36_dialog_content = "O resto dos Eclipsitas está recuando. Mesmo sendo irracionais, eles sabem o que é o medo.",
  ui_story_2004_1_37_dialog_content = "Ei, Eclipsitas!",
  ui_story_2004_1_38_dialog_content = "Não ousem voltar!",
  ui_story_2004_1_39_dialog_content = "É! Lutar realmente me esgota...",
  ui_story_2004_1_40_dialog_content = "Nem pensem em voltar!",
  ui_story_2004_1_41_dialog_content = "Por algum motivo, os bandidos estão mais ativos do que o normal e até ousaram cruzar a fronteira de Northland.",
  ui_story_2004_1_42_dialog_content = "Vossa Majestade...",
  ui_story_2004_1_43_dialog_content = "Minha irmã parece muito preocupada também...",
  ui_story_2004_1_44_dialog_content = "As sombras estão se mexendo. Esse é o momento em que as estrelas se misturam...",
  ui_story_2004_1_45_dialog_content = "Espere um minuto, o líder não está morto!",
  ui_story_2004_1_46_dialog_content = "Vossa Majestade, devemos ir atrás dele e derrotá-lo mais uma vez?",
  ui_story_2004_1_47_dialog_content = "Não será necessário.",
  ui_story_2004_1_48_dialog_content = "A menos que atravesse a fronteira de Northland. Meu gelo e neve protegem apenas meu povo.",
  ui_story_2004_1_49_dialog_content = "<color=#e8d9bb>Bethlehem estendeu a mão e um floco de neve caiu suavemente sobre ela, mas não derreteu.</color>",
  ui_story_2004_1_50_dialog_content = "Está nevando!",
  ui_story_2004_1_51_dialog_content = "Bem, neva o ano todo em Northland.",
  ui_story_2004_1_52_dialog_content = "O chão está coberto novamente por um espesso tapete de neve, como algodão, macio e branco...",
  ui_story_2004_1_53_dialog_content = "Você vai fazer um boneco de neve de quem dessa vez? Que tal fazer um seu?",
  ui_story_2004_1_54_dialog_content = "Vamos!",
  ui_story_2004_1_55_dialog_content = "Ei, espere um momento!",
  ui_story_2004_1_56_dialog_content = "Enlouqueceu!? Eu não sou tão pequena!",
  ui_story_2004_1_57_dialog_content = "<color=#e8d9bb>Sob a Aurora, este mundo coberto de neve ficou em silêncio, e os ecos enfraquecidos de combate foram engolidos pelo ar gelado.</color>",
  ui_story_2004_1_58_dialog_content = "Flocos de neve? \"A neve cai com mensageiros vindos do alto”...",
  ui_story_2004_1_59_dialog_content = "Nikinis.",
  ui_story_2004_1_60_dialog_content = "Vossa Majestade.",
  ui_story_2004_1_61_dialog_content = "Prepare-se para dar boas-vindas.",
  ui_story_2004_1_62_dialog_content = "Uma <color=#FFB400>visitante de outra terra</color> está chegando.",
  ui_story_2004_2_1_dialog_content = "Carleen, não seja grosseira. Você representa a imagem e honra de Lumópolis.",
  ui_story_2004_2_2_dialog_content = "Sim, meu Senhor. Eu compreendo.",
  ui_story_2004_2_3_dialog_content = "Vá agora.",
  ui_story_2004_2_4_dialog_content = "Sua Alteza Carleen, ainda tão jovem, tem que viajar para o reino distante de Northland...",
  ui_story_2004_2_5_dialog_content = "Os Eclipsitas estão em ascensão. Com a situação em um momento tão crítico, essa é uma escolha necessária.",
  ui_story_2004_2_6_dialog_content = "Mais cedo ou mais tarde, ela carregará todo o peso de Lumópolis e será responsável pela vida de seus cidadãos...",
  ui_story_2004_2_7_dialog_content = "Tudo isso é necessário.",
  ui_story_2004_2_8_dialog_content = "Carleen...",
  ui_story_2004_2_9_dialog_content = "*Respira fundo*",
  ui_story_2004_2_10_dialog_content = "Ufa...",
  ui_story_2004_2_11_dialog_content = "*Respirando fundo*",
  ui_story_2004_2_12_dialog_content = "Está nervosa?",
  ui_story_2004_2_13_dialog_content = "Aaaah!",
  ui_story_2004_2_14_dialog_content = "S-sinto muito. Isso foi rude da minha parte!",
  ui_story_2004_2_15_dialog_content = "Assustada?",
  ui_story_2004_2_16_dialog_content = "Sim, estou com um pouco de medo... Essa é a minha primeira vez em Northland...",
  ui_story_2004_2_17_dialog_content = "Mãe disse que Northland é coberta de gelo e neve, um \"Reino Gelado\" romântico, porém frio.",
  ui_story_2004_2_18_dialog_content = "A luz dos vagalumes guia as almas para a floresta do sono eterno, e o narciso branco lamenta seu destino às margens do lago...",
  ui_story_2004_2_19_dialog_content = "Quando eu estava em Lumópolis, raramente via neve.",
  ui_story_2004_2_20_dialog_content = "Nunca vi um reino tão congelado. É lindo.",
  ui_story_2004_2_21_dialog_content = "Mas estar aqui de verdade ainda me deixa um pouco nervosa.",
  ui_story_2004_2_22_dialog_content = "*Puxa o rosto de Carleen*",
  ui_story_2004_2_23_dialog_content = "Ah! Isso é... costume em Northland?",
  ui_story_2004_2_24_dialog_content = "Hehe! Não, é que você é tão fofa que não consigo evitar.",
  ui_story_2004_2_25_dialog_content = "Fique tranquila. Como convidada de honra em Northland, todos aqui certamente irão tratá-la com gentileza.",
  ui_story_2004_2_26_dialog_content = "A Rainha do Norte... como ela é?",
  ui_story_2004_2_27_dialog_content = "Sua Majestade...",
  ui_story_2004_2_28_dialog_content = "Imponente? Majestosa? De bom coração?",
  ui_story_2004_2_29_dialog_content = "É difícil descrevê-la. Minhas palavras são tão frias quanto as planícies geladas.",
  ui_story_2004_2_30_dialog_content = "Ah, aqui estamos! Enfim, você a reconhecerá quando a vir!",
  ui_story_2004_2_31_dialog_content = "Bem-vinda ao trono eterno de Northland,",
  ui_story_2004_2_32_dialog_content = "o <color=#FFB400>Palácio Invernal</color>.",
  ui_story_2004_2_33_dialog_content = "(Que grande palácio... Parece ainda mais magnífico do que Lumópolis.)",
  ui_story_2004_2_34_dialog_content = "(Tudo aqui é feito de cristais de gelo?)",
  ui_story_2004_2_35_dialog_content = "(Como são delicados e sofisticados, e não derretem.)",
  ui_story_2004_2_36_dialog_content = "Visitante que vem de longe, olhe aqui.",
  ui_story_2004_2_37_dialog_content = "Ah!",
  ui_story_2004_2_38_dialog_content = "Vossa... Vossa Majestade... Bom dia.",
  ui_story_2004_2_39_dialog_content = "...",
  ui_story_2004_2_40_dialog_content = "Carleen de Lumópolis... Desejo-lhe os melhores votos.",
  ui_story_2004_2_41_dialog_content = "Que a amizade entre nossos dois países dure para sempre, até que a Aurora acabe.",
  ui_story_2004_2_42_dialog_content = "...",
  ui_story_2004_2_43_dialog_content = "(Por que Sua Majestade não diz nada? Falei algo errado?)",
  ui_story_2004_2_44_dialog_content = "<color=#e8d9bb>Bethlehem levantou-se do trono e passou direto por Carleen como se não a tivesse visto. Um constrangimento embaraçoso congelou o ar.</color>",
  ui_story_2004_2_45_dialog_content = "(Eu realmente fiz algo errado?)",
  ui_story_2004_2_46_dialog_content = "Visitante?",
  ui_story_2004_2_47_dialog_content = "Hã?",
  ui_story_2004_2_48_dialog_content = "Rápido. Sua Majestade está esperando lá fora.",
  ui_story_2004_2_49_dialog_content = "Ah! Tá bom!",
  ui_story_2004_2_X1_dialog_content = "(Ah, é ela! Sua Majestade!)",
  ui_story_2004_2_X2_dialog_content = "(Não, não fique nervosa. Acalme-se, Carleen. Vai dar tudo certo.)",
  ui_story_2004_2_X3_dialog_content = "(Como você praticou...)",
  ui_story_2004_2_X4_dialog_content = "V-Vossa Majestade, nós…",
  ui_story_2004_2_50_dialog_content = "Schwartz a enviou aqui para aprender como usar uma espada.",
  ui_story_2004_2_51_dialog_content = "Sendo assim, vamos começar agora.",
  ui_story_2004_2_X5_dialog_content = "Hã?",
  ui_story_2004_2_52_dialog_content = "E-Eclipsitas!? Como isso...",
  ui_story_2004_2_X52_dialog_content = "E invocou outros aliados...",
  ui_story_2004_2_53_dialog_content = "Não se preocupe. É a magia da Rainha, uma miragem de gelo e neve. Apenas dê seu melhor.",
  ui_story_2004_2_54_dialog_content = "Aaarrgh!",
  ui_story_2004_2_X6_dialog_content = "Eu... venci?",
  ui_story_2004_2_X7_dialog_content = "Ficar menos alerta agora só levará à derrota.",
  ui_story_2004_2_X8_dialog_content = "Hã?!",
  ui_story_2004_2_55_dialog_content = "Ai... Ai...",
  ui_story_2004_2_56_dialog_content = "Isso é tudo que você tem?",
  ui_story_2004_2_57_dialog_content = "Desculpe, Vossa Majestade.",
  ui_story_2004_2_X9_dialog_content = "Movimentos descoordenados, distração e confusão após ganhar uma breve vantagem.",
  ui_story_2004_2_58_dialog_content = "E na realidade... você não consegue nem quebrar o gelo na superfície.",
  ui_story_2004_2_59_dialog_content = "Se estivesse enfrentando um Eclipsita de verdade, sua vida estaria acabada agora.",
  ui_story_2004_2_60_dialog_content = "Eu... sinto muito...",
  ui_story_2004_2_X60_dialog_content = "Retire essas palavras inúteis.",
  ui_story_2004_2_61_dialog_content = "Você é fraca... O vento e a neve de Northland vão te devorar instantaneamente.",
  ui_story_2004_2_62_dialog_content = "Se não consegue passar nesse teste, talvez Lumópolis seja mesmo um clima mais adequado para você.",
  ui_story_2004_2_63_dialog_content = "Mãe, Northland é de fato uma terra congelada.",
  ui_story_2004_2_64_dialog_content = "Ela é como um pintinho, tremendo no vento frio…",
  ui_story_2004_2_65_dialog_content = "A irmã não aguenta mais...",
  ui_story_2004_2_66_dialog_content = "Porque essa é a única maneira do brilho de Lumópolis se manter vivo.",
  ui_story_2004_2_67_dialog_content = "Eles enviaram uma garotinha em uma missão dessas. Isso é a cara daqueles nobres hipócritas de Lumópolis.",
  ui_story_2004_3_1_dialog_content = "*Arruma documentos na mesa*",
  ui_story_2004_3_2_dialog_content = "Uma maré negra de Eclipsitas está se juntando para invadir Northland.",
  ui_story_2004_3_3_dialog_content = "Já vi isso acontecer muitas vezes. É muito perigoso...",
  ui_story_2004_3_4_dialog_content = "O vento e a neve manchados de sangue, a escuridão consumindo a luz...",
  ui_story_2004_3_5_dialog_content = "Eu vi a noite sem fim, como se a última vela fosse apagada.",
  ui_story_2004_3_6_dialog_content = "Mas a Aurora ainda brilha levemente pela noite...",
  ui_story_2004_3_7_dialog_content = "Mesmo que esteja cintilando.",
  ui_story_2004_3_8_dialog_content = "Estou muito cansada para continuar pensando… Talvez eu deva tomar meu chá da tarde.",
  ui_story_2004_3_9_dialog_content = "Ah-hah!",
  ui_story_2004_3_10_dialog_content = "Irmã... Estou tão nervosa... E se os Eclipsitas a atacarem de novo!?",
  ui_story_2004_3_11_dialog_content = "Ai... Meu suor congelou... e minha mão está grudada na minha arma...",
  ui_story_2004_3_X1_dialog_content = "Continue... Não chore.",
  ui_story_2004_3_X2_dialog_content = "Mais uma vez...",
  ui_story_2004_3_12_dialog_content = "Está olhando o que, Nikinis?",
  ui_story_2004_3_13_dialog_content = "Bom dia, Vossa Majestade. Estou olhando para Sua Alteza, Carleen.",
  ui_story_2004_3_14_dialog_content = "Gelescer!",
  ui_story_2004_3_15_dialog_content = "Wooga.",
  ui_story_2004_3_16_dialog_content = "(Relaxe... Mantenha a calma.)",
  ui_story_2004_3_X3_dialog_content = "(Altura... Essa é a minha vantagem! Posso atacar sua parte inferior...)",
  ui_story_2004_3_17_dialog_content = "(E saber sua fraqueza também é uma grande vantagem! Sua fraqueza...)",
  ui_story_2004_3_18_dialog_content = "Aqui está!",
  ui_story_2004_3_19_dialog_content = "Ahhh!",
  ui_story_2004_3_20_dialog_content = "Falhei... de novo... Gelo...",
  ui_story_2004_3_21_dialog_content = "(Primeiramente, derrote seus aliados...)",
  ui_story_2004_3_22_dialog_content = "(Mas ele continua chamando mais aliados. É como uma parede de ferro impenetrável sem uma única brecha.)",
  ui_story_2004_3_23_dialog_content = "Mas não posso desistir!",
  ui_story_2004_3_24_dialog_content = "Essa ferida dói e... meus pés também estão congelando. Eles estão absolutamente congelados.",
  ui_story_2004_3_25_dialog_content = "Mas não posso desistir... Vamos...",
  ui_story_2004_3_26_dialog_content = "Ahh!",
  ui_story_2004_3_27_dialog_content = "Wooga?",
  ui_story_2004_3_28_dialog_content = "Ah, caiu. É só uma criança.",
  ui_story_2004_3_29_dialog_content = "Tá doendo...",
  ui_story_2004_3_30_dialog_content = "Aquela não é Lady Nikinis e...",
  ui_story_2004_3_31_dialog_content = "Sua Majestade!",
  ui_story_2004_3_32_dialog_content = "*Olha para o lado em silêncio*",
  ui_story_2004_3_33_dialog_content = "(Ops! Estou toda suja!)",
  ui_story_2004_3_34_dialog_content = "(Coberta de neve, descabelada e vestido cheio de lama...)",
  ui_story_2004_3_35_dialog_content = "(O que devo fazer!?)",
  ui_story_2004_3_36_dialog_content = "Ela está preocupada com sua aparência. Ela é tão fofa, como um bonequinho de neve!",
  ui_story_2004_3_X4_dialog_content = "...",
  ui_story_2004_3_37_dialog_content = "(Reverência, faça uma reverência primeiro.)",
  ui_story_2004_3_38_dialog_content = "Que o gelo e a neve a abençoem. Bom dia, Vossa Majestade, Lady Nikinis.",
  ui_story_2004_3_39_dialog_content = "Bom dia, jovem Carleen. Pode seguir com o que estava fazendo.",
  ui_story_2004_3_40_dialog_content = "Certo, tudo bem!",
  ui_story_2004_3_41_dialog_content = "Farei o meu melhor para derrotá-lo e completar essa prova, Vossa Majestade!",
  ui_story_2004_3_42_dialog_content = "Majestade, se pudesse confortar Sua Alteza Carleen, ela ficaria muito contente.",
  ui_story_2004_3_43_dialog_content = "Desde aquele dia, ela aparece todos os dias para esse desafio.",
  ui_story_2004_3_44_dialog_content = "Ela cai, e então se levanta novamente... Ela cai,",
  ui_story_2004_3_45_dialog_content = "e depois fica em pé mais uma vez.",
  ui_story_2004_3_46_dialog_content = "Afinal, ela é uma criança que não tem técnica, mas fez grandes progressos.",
  ui_story_2004_3_47_dialog_content = "...",
  ui_story_2004_3_48_dialog_content = "A irmã também acha.",
  ui_story_2004_3_49_dialog_content = "Confortá-la? Não é necessário.",
  ui_story_2004_3_50_dialog_content = "Sua Majestade... foi embora.",
  ui_story_2004_4_1_dialog_content = "Um sonho? Uma memória tão distante...",
  ui_story_2004_4_2_dialog_content = "Shaya.",
  ui_story_2004_4_3_dialog_content = "Essa voz...",
  ui_story_2004_4_4_dialog_content = "Shaya.",
  ui_story_2004_4_5_dialog_content = "Isso é um pesadelo?",
  ui_story_2004_4_6_dialog_content = "Os Eclipsitas estão se aproximando. Se continuarem a invadir, Northland será completamente destruída.",
  ui_story_2004_4_7_dialog_content = "Mas a Aurora nos deu uma chance de sobreviver. É o poder do gelo e da neve.",
  ui_story_2004_4_8_dialog_content = "<color=#e8d9bb>Cristais de gelo brancos brilhavam na palma da mão da mulher, extremamente frios e girando com a aura de outrora.</color>",
  ui_story_2004_4_9_dialog_content = "O frio condensou-se no frágil cristal de gelo, escondendo sua verdadeira força.",
  ui_story_2004_4_X1_dialog_content = "Uma vez liberado, ele destruirá tudo e derrotará todos aqueles que ousarem invadir esse lugar.",
  ui_story_2004_4_X2_dialog_content = "Porém, o preço também é colossal...",
  ui_story_2004_4_10_dialog_content = "<color=#FFB400>Temo que você nunca deixe Northland.</color>",
  ui_story_2004_4_X3_dialog_content = "Essa espada de dois gumes é muito afiada. Ao derrotar o inimigo, ela deixa cicatrizes no corpo e na mente que não se curam.",
  ui_story_2004_4_11_dialog_content = "O tempo não deixa sua marca no seu rosto, mas tira tudo de você.",
  ui_story_2004_4_12_dialog_content = "Acompanhada apenas de neve, você deve enfrentar o mundo sozinha.",
  ui_story_2004_4_13_dialog_content = "Argh... Argh...",
  ui_story_2004_4_14_dialog_content = "Eles estão aqui.",
  ui_story_2004_4_15_dialog_content = "Eu já sabia.",
  ui_story_2004_4_16_dialog_content = "O governo e o poder não são apenas formas de controle, também representam uma importante missão e grandes dificuldades.",
  ui_story_2004_4_17_dialog_content = "Mesmo se houver uma avalanche, alguém precisa ficar em seu caminho, defendendo seu povo.",
  ui_story_2004_4_18_dialog_content = "Eu me ofereci para entrar nessa prisão e nunca hesitei diante da adversidade.",
  ui_story_2004_4_19_dialog_content = "O que você escolheria?",
  ui_story_2004_4_20_dialog_content = "Eu pegaria o cetro.",
  ui_story_2004_4_21_dialog_content = "Eu controlaria o gelo e a neve e protegeria Northland.",
  ui_story_2004_4_22_dialog_content = "Mas uma prisão ainda é uma prisão.",
  ui_story_2004_4_23_dialog_content = "<color=#e8d9bb>Um, dois, inúmeros Eclipsitas. Bethlehem lutou sozinha contra eles em um combate sem fim.</color>",
  ui_story_2004_4_24_dialog_content = "<color=#e8d9bb>Por fim, ela derrotou todos os seus inimigos e caminhou à frente, encontrando a jovem Carleen parada ali.</color>",
  ui_story_2004_4_25_dialog_content = "Não é apenas o meu sonho, mas o dela também...",
  ui_story_2004_4_26_dialog_content = "Aurora e Phospherus, ouçam meu apelo. Eu quero...",
  ui_story_2004_4_27_dialog_content = "Carleen, o que está fazendo?",
  ui_story_2004_4_28_dialog_content = "Ah! Vossa Majestade! Estou rezando... para a Aurora.",
  ui_story_2004_4_29_dialog_content = "Rezou pelo quê?",
  ui_story_2004_4_30_dialog_content = "Rezei por...",
  ui_story_2004_4_31_dialog_content = "Majestade, se eu não mantiver segredo, ainda se tornará realidade?",
  ui_story_2004_4_32_dialog_content = "É mais seguro guardar segredos no coração, mas prefiro apresentá-los à Aurora.",
  ui_story_2004_4_33_dialog_content = "Porque eu faço o que eu falo... Sou sempre fiel à minha palavra.",
  ui_story_2004_4_34_dialog_content = "Você é incrível, Vossa Majestade...",
  ui_story_2004_4_35_dialog_content = "Então eu... Deixe-me contar em segredo também!",
  ui_story_2004_4_36_dialog_content = "Meu desejo é... ser forte. Ser tão forte quanto você.",
  ui_story_2004_4_37_dialog_content = "Para se tornar forte...",
  ui_story_2004_4_38_dialog_content = "Sou tão fraca agora...",
  ui_story_2004_4_39_dialog_content = "Não sei quando começou, mas parece que a minha vida virou uma completa bagunça de repente.",
  ui_story_2004_4_40_dialog_content = "Minha mãe está doente e eu não a vejo há muito tempo.",
  ui_story_2004_4_X4_dialog_content = "Meu pai vive emburrado como se nunca fosse sorrir novamente.",
  ui_story_2004_4_X5_dialog_content = "Não tenho notícias da minha irmã.",
  ui_story_2004_4_X6_dialog_content = "Lembro que ela é carinhosa e gentil, mas não consigo mais lembrar do seu rosto direito.",
  ui_story_2004_4_41_dialog_content = "Até a indestrutível Lumópolis começou a desmoronar.",
  ui_story_2004_4_X7_dialog_content = "Os muros da cidade continuam fortes como sempre, mas agora me parecem tão frágeis...",
  ui_story_2004_4_42_dialog_content = "Embora eu não possa fazer nada sobre isso,",
  ui_story_2004_4_43_dialog_content = "Se eu fosse tão poderoso quanto você, tudo ficaria bem.",
  ui_story_2004_4_44_dialog_content = "Tudo ficaria bem? Heh.",
  ui_story_2004_4_45_dialog_content = "Hã? Você acabou de dar uma risada?",
  ui_story_2004_4_46_dialog_content = "Você... está rindo de mim?",
  ui_story_2004_4_47_dialog_content = "Não, sua pequena oração é preciosa como uma estrela brilhante durante a noite.",
  ui_story_2004_4_48_dialog_content = "(Chega a quase ser um elogio!)",
  ui_story_2004_4_49_dialog_content = "Então, pelo que você oraria?",
  ui_story_2004_4_50_dialog_content = "Você já é tão poderosa. Existe mais alguma coisa que você possa querer?",
  ui_story_2004_4_51_dialog_content = "É claro que sim.",
  ui_story_2004_4_52_dialog_content = "É claro que existe algo que eu quero.",
  ui_story_2004_4_53_dialog_content = "É o mesmo que você quer.",
  ui_story_2004_5_1_dialog_content = "Esquerda! À sua esquerda!",
  ui_story_2004_5_2_dialog_content = "Caramba! Essa foi por pouco. Acho que existe uma chance!",
  ui_story_2004_5_3_dialog_content = "Gelescer!!",
  ui_story_2004_5_4_dialog_content = "Incrível! Carleen, você é tão poderosa!",
  ui_story_2004_5_5_dialog_content = "Seu treinamento valeu a pena. Seu desejo de enfrentar o líder dos Eclipsitas sozinha não era apenas um sonho.",
  ui_story_2004_5_6_dialog_content = "Ahhh!!!",
  ui_story_2004_5_7_dialog_content = "Ai!!",
  ui_story_2004_5_8_dialog_content = "Ah! Caiu!",
  ui_story_2004_5_9_dialog_content = "Retire essas palavras.",
  ui_story_2004_5_10_dialog_content = "Não, não importa! Ainda posso lutar!",
  ui_story_2004_5_11_dialog_content = "O mais importante é compreender totalmente o poder Lúmina e abraçá-lo com cuidado!",
  ui_story_2004_5_12_dialog_content = "Como Louise, por exemplo. O poder que a chama é a Lúmina da Floresta.",
  ui_story_2004_5_13_dialog_content = "Quando usado corretamente, pode liberar uma força poderosa.",
  ui_story_2004_5_14_dialog_content = "Quanto à Carleen...",
  ui_story_2004_5_15_dialog_content = "Deve ser Água! Essa Lúmina...",
  ui_story_2004_5_X1_dialog_content = "Como vou explicar... Embora eu não consiga ver, posso sentir seu sabor de mirtilo!",
  ui_story_2004_5_16_dialog_content = "Compreender a Lúmina…",
  ui_story_2004_5_17_dialog_content = "Certo! Use o poder da sua mente para senti-la. Permita-me demonstrar!",
  ui_story_2004_5_18_dialog_content = "Sinta... Concentre-se, concentre-se...",
  ui_story_2004_5_19_dialog_content = "Tem cheiro de... foca assada. É torrado e crocante, quente e saboroso.",
  ui_story_2004_5_20_dialog_content = "Ah! Tô com fome.",
  ui_story_2004_5_21_dialog_content = "Falando nisso, também tô.",
  ui_story_2004_5_22_dialog_content = "Não olhe pra mim. Eu não tô...",
  ui_story_2004_5_23_dialog_content = "Com fome...",
  ui_story_2004_5_24_dialog_content = "Eu também tô com fome.",
  ui_story_2004_5_25_dialog_content = "Crianças boas não podem mentir.",
  ui_story_2004_5_26_dialog_content = "Bem, lá vamos nós de novo, Carleen!",
  ui_story_2004_5_27_dialog_content = "Espere até o derrotarmos… Aí vamos todas comer algo saboroso!",
  ui_story_2004_5_28_dialog_content = "Beleza!",
  ui_story_2004_5_29_dialog_content = "Ela se tornou muito amiga de Noah e Louise.",
  ui_story_2004_5_30_dialog_content = "Ela está treinando aqui todos os dias há um mês.",
  ui_story_2004_5_31_dialog_content = "Mesmo quando nevava forte, ela chegava cedo e treinava até tarde da noite. Ela era uma ótima menina.",
  ui_story_2004_5_32_dialog_content = "Ela parece mais poderosa do que antes. Embora ainda precise aperfeiçoar sua habilidade, ela aprendeu como descobrir os pontos fracos dos Eclipsitas.",
  ui_story_2004_5_33_dialog_content = "Dessa vez, ela pode conseguir.",
  ui_story_2004_5_X33_dialog_content = "Ela tem um longo caminho a percorrer, mas...",
  ui_story_2004_5_34_dialog_content = "Vamos aguardar e observar.",
  ui_story_2004_5_35_dialog_content = "Hã?",
  ui_story_2004_5_36_dialog_content = "Você está mesmo surpresa? Você parece me achar muito severa.",
  ui_story_2004_5_37_dialog_content = "Eu realmente não gosto de Lumópolis, mas Carleen...",
  ui_story_2004_5_38_dialog_content = "Como você disse, ela é uma boa menina.",
  ui_story_2004_5_39_dialog_content = "Golpe final!",
  ui_story_2004_5_40_dialog_content = "E-eu o derrotei!",
  ui_story_2004_5_41_dialog_content = "Eu o derrotei!",
  ui_story_2004_5_42_dialog_content = "Ele se dissipou em flocos de neve, totalmente congelado.",
  ui_story_2004_5_43_dialog_content = "Embora os flocos de neve sejam minúsculos, cada um é único.",
  ui_story_2004_5_44_dialog_content = "Observe esse hexagonal, parece que foi cortado em finas fatias. Isso é chamado de cristal lamelar. Parece uma pintura.",
  ui_story_2004_5_45_dialog_content = "Esse aqui, com pontas em ambas as extremidades parecendo agulhas, é chamado de cristal acicular.",
  ui_story_2004_5_46_dialog_content = "São adoráveis. Essa é a primeira vez que olho para esses flocos de neve com tanto cuidado desde que vim pra cá.",
  ui_story_2004_5_47_dialog_content = "E os flocos de neve que Carleen criou são lindos também!",
  ui_story_2004_5_X2_dialog_content = "S-sério?",
  ui_story_2004_5_X3_dialog_content = "Os flocos de neve só podem surgir em ambientes extremamente frios.",
  ui_story_2004_5_X4_dialog_content = "Temperaturas frias o suficiente pra te congelar!",
  ui_story_2004_5_X5_dialog_content = "Mas acho que vale a pena por flocos de neve tão lindos!",
  ui_story_2004_5_X6_dialog_content = "E é claro que fui esperta o bastante de usar roupas grossas pra me manter aquecida enquanto observava os flocos de neve.",
  ui_story_2004_5_X7_dialog_content = "Ah, Carleen... Você tá com frio?",
  ui_story_2004_5_X8_dialog_content = "Um-um pouco.",
  ui_story_2004_5_X9_dialog_content = "Se você sentir frio, eu te dou um abraço. Que tal?",
  ui_story_2004_5_X10_dialog_content = "Humm... Tão quentinho.",
  ui_story_2004_5_48_dialog_content = "Ah! Vossa Majestade!",
  ui_story_2004_5_49_dialog_content = "Vossa Majestade! Que o gelo e a neve a abençoem.",
  ui_story_2004_5_50_dialog_content = "E-eu derrotei os Eclipsitas e concluí o seu teste!",
  ui_story_2004_5_51_dialog_content = "Embora eu tenha certeza de que, na sua opinião, meu desempenho não foi perfeito... Ainda há muito o que melhorar.",
  ui_story_2004_5_52_dialog_content = "E eu... não diria que trabalhei muito duro...",
  ui_story_2004_5_53_dialog_content = "Vou dizer apenas que nunca ficarei satisfeita com a minha força! Vou continuar aprendendo!",
  ui_story_2004_5_54_dialog_content = "Por que você se esforça tanto? Você ainda é tão jovem.",
  ui_story_2004_5_55_dialog_content = "Embora eu tenha lhe passado um teste tão difícil, não teria problema fugir. Ninguém teria pensado menos de você.",
  ui_story_2004_5_56_dialog_content = "Nem o seu pai teria dito alguma coisa.",
  ui_story_2004_5_57_dialog_content = "Foi tudo por Lumópolis. Quero defender o nosso lar, o lugar onde meu povo viveu feliz.",
  ui_story_2004_5_58_dialog_content = "Então você veio para Northland sozinha, sem medo no coração.",
  ui_story_2004_5_59_dialog_content = "Sim.",
  ui_story_2004_5_X11_dialog_content = "Carleen...",
  ui_story_2004_5_X12_dialog_content = "(Há uma certa preocupação em seu olhar, mas há mais determinação.)",
  ui_story_2004_5_X13_dialog_content = "(Ela parece estar ciente do que o futuro a reserva, tanto em relação à Joshua quanto às responsabilidades que deve assumir.)",
  ui_story_2004_5_X14_dialog_content = "(Mas seja lá o que vier, ela está pronta para qualquer coisa que cruze seu caminho.)",
  ui_story_2004_5_60_dialog_content = "Ela parece um pouco comigo. Schwartz até previu isso, não foi?",
  ui_story_2004_5_61_dialog_content = "Mas tudo bem.",
  ui_story_2004_5_62_dialog_content = "O quê?",
  ui_story_2004_5_63_dialog_content = "Carleen, você ficará mais forte, mas mais cedo ou mais tarde você vai entender...",
  ui_story_2004_5_64_dialog_content = "O preço de muito poder é a solidão sem fim. Você descobrirá isso em breve.",
  ui_story_2004_5_65_dialog_content = "Agora, vista uma roupa aquecida e tenha um bom descanso.",
  ui_story_2004_5_66_dialog_content = "Amanhã você enfrentará seu verdadeiro teste.",
  ui_story_2004_6_1_dialog_content = "Essa é a fronteira de Northland. O gelo e a neve que se estendem por milhares de quilômetros acabam aqui.",
  ui_story_2004_6_2_dialog_content = "Há um santuário gelado dentro dessas fronteiras, mas o mundo exterior é extremamente perigoso e cheio de Eclipsitas.",
  ui_story_2004_6_3_dialog_content = "Olhe. Eles estão vindo.",
  ui_story_2004_6_4_dialog_content = "Grrrr!",
  ui_story_2004_6_5_dialog_content = "Hã!? É o mesmo de antes!",
  ui_story_2004_6_6_dialog_content = "Ele trouxe alguns amiguinhos com ele. Talvez eles tenham nos subestimado?",
  ui_story_2004_6_7_dialog_content = "Não, espere um momento...",
  ui_story_2004_6_8_dialog_content = "Atrás dele... Há mais deles acompanhando...",
  ui_story_2004_6_9_dialog_content = "Tem mais vindo por trás!",
  ui_story_2004_6_10_dialog_content = "São muitos deles... Esses Eclipsitas são malucos?",
  ui_story_2004_6_11_dialog_content = "Você viu o líder deles?",
  ui_story_2004_6_12_dialog_content = "Ele tá usando poderes sombrios pra invocar seus lacaios em uma tentativa de corromper a neve pura.",
  ui_story_2004_6_13_dialog_content = "Carleen, deixe-me ver o que você aprendeu nos últimos dias. Acabe com ele.",
  ui_story_2004_6_14_dialog_content = "Será… Será que realmente consigo?",
  ui_story_2004_6_15_dialog_content = "Embora eu queira ficar mais forte, na verdade, eu...",
  ui_story_2004_6_16_dialog_content = "Não  tenha medo. Você tá pronta pra isso.",
  ui_story_2004_6_17_dialog_content = "Hã?",
  ui_story_2004_6_19_dialog_content = "O trabalho duro compensa. Acredite em si mesma, em sua crença e no seu objetivo.",
  ui_story_2004_6_20_dialog_content = "Hah! O último deles!",
  ui_story_2004_6_21_dialog_content = "Não podemos deixá-los escapar dessa vez.",
  ui_story_2004_6_22_dialog_content = "Já tomei conta dos que estavam desse lado aqui também!",
  ui_story_2004_6_23_dialog_content = "Eles pareciam invencíveis no início, mas acabaram sendo meio que uma piada.",
  ui_story_2004_6_24_dialog_content = "Quem sabe quando eles aprenderão a lição, mas eu com certeza não me importo de lutar contra eles.",
  ui_story_2004_6_25_dialog_content = "Será que a Carleen está bem?",
  ui_story_2004_6_26_dialog_content = "Já tá escuro.",
  ui_story_2004_6_27_dialog_content = "(Sinta a força da Luz. Sim, veja a fraqueza do inimigo.)",
  ui_story_2004_6_28_dialog_content = "(O ritmo. Não erre o ritmo.)",
  ui_story_2004_6_29_dialog_content = "(Não consigo mais levantar os braços e meu rosto está congelando... mas com certeza não vou cair antes dele!)",
  ui_story_2004_6_30_dialog_content = "(Isso não é nada, já conheço todos os seus truques. Mais devagar agora... aos pouquinhos...)",
  ui_story_2004_6_31_dialog_content = "Agora!",
  ui_story_2004_6_32_dialog_content = "Carleen! Você... Você conseguiu!",
  ui_story_2004_6_33_dialog_content = "Eu derrotei um Eclipsita de verdade, um Eclipsita muito poderoso... Eu nunca pensei que conseguiria.",
  ui_story_2004_6_34_dialog_content = "Bom trabalho.",
  ui_story_2004_6_35_dialog_content = "<color=#e8d9bb>Bethlehem deu um passo à frente e tocou a cabeça de Carleen gentilmente.</color>",
  ui_story_2004_6_36_dialog_content = "Embora a luz esteja fraca agora, ela iluminará o céu inteiro um dia.",
  ui_story_2004_6_37_dialog_content = "Carleen, olhe.",
  ui_story_2004_6_38_dialog_content = "<color=#e8d9bb>O céu de Northland estava tão bonito, com a bela Aurora que pairava acima de nós como se fosse um sonho.</color>",
  ui_story_2004_6_39_dialog_content = "Na escuridão da noite, quase parece que você pode estender a mão e tocar a Aurora que flutua levemente.",
  ui_story_2004_6_40_dialog_content = "É tão lindo...",
  ui_story_2004_6_41_dialog_content = "Northland é um lugar tão bonito e digno de ser protegido com a vida.",
  ui_story_2004_6_42_dialog_content = "E Lumópolis? Que tipo de lugar é Lumópolis pra você?",
  ui_story_2004_6_43_dialog_content = "Lumópolis fica mais alto que o céu, emanando sua luz lá de cima.",
  ui_story_2004_6_44_dialog_content = "Meu pai, minha mãe, os anjos e todas as pessoas maravilhosas vivem aqui.",
  ui_story_2004_6_45_dialog_content = "Acredito de coração que seja tão bonita quanto Northland.",
  ui_story_2004_6_46_dialog_content = "É mesmo?",
  ui_story_2004_6_47_dialog_content = "Eu ouvi de meu pai uma vez que você tem protegido esta terra sozinha por muito tempo.",
  ui_story_2004_6_48_dialog_content = "É realmente muito solitário ser assim tão forte?",
  ui_story_2004_6_49_dialog_content = "Sim, é. A solidão é extremamente fria. Mais fria que o gelo. No entanto, não me arrependo.",
  ui_story_2004_6_50_dialog_content = "Por este belo reino de Northland e pela bela Aurora.",
  ui_story_2004_6_51_dialog_content = "Você compreende, não?",
  ui_story_2004_6_52_dialog_content = "Entendi.",
  ui_story_2004_6_X1_dialog_content = "Mesmo que ninguém mais compreenda, mesmo que eu tenha que suportar um grande sofrimento... tenho que ser a única.",
  ui_story_2004_6_X2_dialog_content = "Aquela que carrega o peso do mundo e protege todos nós.",
  ui_story_2004_6_X3_dialog_content = "Mesmo que eu fique completamente sozinha.",
  ui_story_2004_6_53_dialog_content = "Que bom. Carleen, você passou no teste.",
  ui_story_2004_6_54_dialog_content = "Agora vou ensinar algumas habilidades de combate de verdade."
}
return config
